B.amL=new A.e("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u064a\u0631\u062a\u0628\u0637 \u0627\u0644\u0625\u0634\u0631\u0627\u0637 \u0627\u0644\u0643\u0644\u0627\u0633\u064a\u0643\u064a (\u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u064a) \u0628\u0646\u0638\u0631\u064a\u0629:",B.a47,1,"\u0627\u0644\u0625\u0634\u0631\u0627\u0637 \u0627\u0644\u0643\u0644\u0627\u0633\u064a\u0643\u064a \u062a\u062c\u0631\u0628\u0629 \u0644\u0628\u0627\u0641\u0644\u0648\u0641 \u0639\u0644\u0649 \u0627\u0644\u0643\u0644\u0628: \u0631\u0628\u0637 \u0627\u0644\u0645\u062b\u064a\u0631 \u0627\u0644\u0645\u062d\u0627\u064a\u062f (\u0627\u0644\u062c\u0631\u0633) \u0628\u0627\u0644\u0645\u062b\u064a\u0631 \u0627\u0644\u0634\u0631\u0637\u064a (\u0627\u0644\u0637\u0639\u0627\u0645) \u0644\u0625\u062d\u062f\u0627\u062b \u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0645\u0643\u062a\u0633\u0628\u0629 (\u0633\u064a\u0644\u0627\u0646 \u0627\u0644\u0644\u0639\u0627\u0628).",u.am)
B.a31=s(["\u0627\u0644\u0628\u0635\u064a\u0631\u0629 \u0648\u0625\u0639\u0627\u062f\u0629 \u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0625\u062f\u0631\u0627\u0643","\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0642\u0631\u064a\u0628","\u0627\u0644\u062a\u0639\u0632\u064a\u0632 (\u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629 \u0648\u0627\u0644\u0639\u0642\u0627\u0628)","\u0627\u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0630\u0627\u062a\u064a \u0644\u0644\u0645\u0639\u0631\u0641\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.at9=new A.e("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0627\u0644\u0625\u0634\u0631\u0627\u0637 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a \u064a\u0631\u062a\u0628\u0637 \u0628\u062f\u0631\u062c\u0629 \u0623\u0633\u0627\u0633\u064a\u0629 \u0628\u0645\u0641\u0647\u0648\u0645:",B.a31,2,"\u0633\u0643\u064a\u0646\u0631 \u0647\u0648 \u0635\u0627\u062d\u0628 \u0627\u0644\u0625\u0634\u0631\u0627\u0637 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a \u0627\u0644\u0642\u0627\u0626\u0645 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0632\u064a\u0632\u061b \u0641\u0627\u0644\u062a\u0639\u0644\u0645 \u064a\u064f\u0636\u0628\u0637 \u0628\u0636\u0628\u0637 \u0639\u0648\u0627\u0642\u0628 \u0627\u0644\u0633\u0644\u0648\u0643 (\u0645\u0643\u0627\u0641\u0623\u0629/\u0639\u0642\u0627\u0628).",u.am)
