B.WG=s(["\u0627\u0644\u0648\u0644\u0627\u062f\u0629 \u0625\u0644\u0649 \u0633\u0646\u062a\u064a\u0646","\u0645\u0646 \u0633\u0646\u062a\u064a\u0646 \u0625\u0644\u0649 7 \u0633\u0646\u0648\u0627\u062a","\u0645\u0646 7 \u0625\u0644\u0649 11 \u0633\u0646\u0629","\u0645\u0646 12 \u0633\u0646\u0629 \u0641\u0645\u0627 \u0641\u0648\u0642","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ao5=new A.e("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u062d\u0633\u0628 \u0628\u064a\u0627\u062c\u064a\u0647\u060c \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062d\u0633\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u064a\u0629 \u062a\u0645\u062a\u062f \u0645\u0646:",B.WG,0,"\u0627\u0644\u062d\u0633\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u064a\u0629 (0-2 \u0633\u0646\u0629): \u064a\u062a\u0639\u0644\u0645 \u0627\u0644\u0637\u0641\u0644 \u0639\u0628\u0631 \u062d\u0648\u0627\u0633\u0647 \u0648\u062d\u0631\u0643\u0627\u062a\u0647 \u062f\u0648\u0646 \u0639\u0645\u0644\u064a\u0627\u062a \u0630\u0647\u0646\u064a\u0629 \u0645\u062c\u0631\u062f\u0629\u060c \u0648\u064a\u0628\u0646\u064a \u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u062f\u064a\u0645\u0648\u0645\u0629.",u.c)
B.a3T=s(["\u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0627\u0644\u0645\u062c\u0631\u062f","\u0627\u0644\u062a\u0645\u0631\u0643\u0632 \u062d\u0648\u0644 \u0627\u0644\u0630\u0627\u062a \u0648\u0627\u0644\u0623\u0646\u0627\u0646\u064a\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629","\u0625\u062a\u0642\u0627\u0646 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0645\u0646\u0637\u0642\u064a\u0629 \u0627\u0644\u0645\u0642\u0644\u0648\u0628\u0629","\u0641\u0647\u0645 \u0627\u0644\u0641\u0631\u0636\u064a\u0627\u062a \u0648\u0627\u0644\u0642\u0648\u0627\u0646\u064a\u0646 \u0627\u0644\u0645\u062c\u0631\u062f\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.as8=new A.e("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u0641\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a (2-7 \u0633\u0646\u0648\u0627\u062a) \u0639\u0646\u062f \u0628\u064a\u0627\u062c\u064a\u0647 \u064a\u062a\u0645\u064a\u0632 \u062a\u0641\u0643\u064a\u0631 \u0627\u0644\u0637\u0641\u0644 \u0628\u0640:",B.a3T,1,"\u0627\u0644\u0637\u0641\u0644 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u064a\u062a\u0635\u0641 \u0628\u0627\u0644\u062a\u0645\u0631\u0643\u0632 \u062d\u0648\u0644 \u0630\u0627\u062a\u0647\u060c \u0648\u0627\u0644\u0638\u0648\u0627\u0647\u0631\u064a\u0629\u060c \u0648\u0639\u062f\u0645 \u0627\u0644\u0627\u0646\u062d\u0641\u0627\u0638\u060c \u0648\u0636\u0639\u0641 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0631\u062a\u064a\u0628.",u.c)
B.ab0=s(["0-2 \u0633\u0646\u0629","2-7 \u0633\u0646\u0648\u0627\u062a","7-11/12 \u0633\u0646\u0629","16 \u0633\u0646\u0629 \u0641\u0645\u0627 \u0641\u0648\u0642","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
