B.adB=s(["\u0639\u0645\u0644\u064a\u0629 \u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0630\u0647\u0646\u064a \u0648\u062a\u0631\u0643\u064a\u0632\u0647 \u0639\u0644\u0649 \u0645\u062b\u064a\u0631 \u0645\u0639\u064a\u0646","\u0639\u0645\u0644\u064a\u0629 \u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629","\u0645\u062c\u0631\u062f \u0631\u062f \u0641\u0639\u0644 \u0644\u0627 \u0625\u0631\u0627\u062f\u064a","\u0645\u0631\u0627\u062f\u0641 \u0644\u0644\u0646\u0633\u064a\u0627\u0646","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.arr=new A.e("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647 \u0641\u064a \u0627\u0644\u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u064a\u064f\u0639\u0631\u064e\u0651\u0641 \u0628\u0623\u0646\u0647:",B.adB,0,"\u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647 \u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0625\u062f\u0631\u0627\u0643\u064a \u0639\u0644\u0649 \u0645\u062b\u064a\u0631 \u062f\u0648\u0646 \u063a\u064a\u0631\u0647\u060c \u0648\u0644\u0647 \u0623\u0634\u0643\u0627\u0644: \u0645\u0646\u062a\u0642\u0649\u060c \u0645\u0642\u0633\u0645\u060c \u0645\u0633\u062a\u0645\u0631.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.a4P=s(["\u0627\u0644\u062d\u0633\u064a\u0629\u060c \u062b\u0645 \u0642\u0635\u064a\u0631\u0629 \u0627\u0644\u0645\u062f\u0649\u060c \u062b\u0645 \u0637\u0648\u064a\u0644\u0629 \u0627\u0644\u0645\u062f\u0649","\u0637\u0648\u064a\u0644\u0629 \u0627\u0644\u0645\u062f\u0649\u060c \u062b\u0645 \u0627\u0644\u062d\u0633\u064a\u0629\u060c \u062b\u0645 \u0642\u0635\u064a\u0631\u0629 \u0627\u0644\u0645\u062f\u0649","\u0642\u0635\u064a\u0631\u0629 \u0627\u0644\u0645\u062f\u0649\u060c \u062b\u0645 \u0637\u0648\u064a\u0644\u0629 \u0627\u0644\u0645\u062f\u0649 \u0641\u0642\u0637","\u0627\u0644\u062d\u0633\u064a\u0629 \u062b\u0645 \u0642\u0635\u064a\u0631\u0629 \u0627\u0644\u0645\u062f\u0649 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aut=new A.e("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u062d\u0633\u0628 \u0646\u0645\u0648\u0630\u062c \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a\u060c \u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u062a\u0645\u0631 \u0639\u0627\u062f\u0629 \u0639\u0628\u0631 \u0627\u0644\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u062a\u0627\u0644\u064a\u0629:",B.a4P,0,"\u0627\u0644\u0646\u0645\u0648\u0630\u062c (\u0623\u062a\u0643\u0646\u0633\u0648\u0646 \u0648\u0634\u064a\u0641\u0631\u064a\u0646): \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629 \u062a\u062f\u062e\u0644 \u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u062d\u0633\u064a\u0629 \u062b\u0645 \u0642\u0635\u064a\u0631\u0629 \u0627\u0644\u0645\u062f\u0649\u060c \u0648\u0628\u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0648\u0627\u0644\u0645\u0639\u0646\u0649 \u062a\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0637\u0648\u064a\u0644\u0629 \u0627\u0644\u0645\u062f\u0649.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.XX=s(["\u0625\u0628\u0646\u062c\u0647\u0627\u0648\u0633","\u0628\u0627\u0641\u0644\u0648\u0641","\u062f\u0648\u0631\u0643\u0627\u064a\u0645","\u062c\u0627\u0631\u062f\u0646\u0631","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aoH=new A.e("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u0645\u0646\u062d\u0646\u0649 \xab\u0627\u0644\u0646\u0633\u064a\u0627\u0646\xbb \u0627\u0644\u0630\u064a \u064a\u0628\u064a\u0646 \u0623\u0646 \u0627\u0644\u0646\u0633\u064a\u0627\u0646 \u064a\u0643\u0648\u0646 \u0633\u0631\u064a\u0639\u0627\u064b \u0628\u0639\u062f \u0627\u0644\u062a\u0639\u0644\u0645 \u0645\u0628\u0627\u0634\u0631\u0629 \u062b\u0645 \u064a\u062a\u0628\u0627\u0637\u0623 \u064a\u0646\u0633\u0628 \u0625\u0644\u0649:",B.XX,0,"\u0625\u0628\u0646\u062c\u0647\u0627\u0648\u0633 \u0635\u0627\u062d\u0628 \u0645\u0646\u062d\u0646\u0649 \u0627\u0644\u0646\u0633\u064a\u0627\u0646: \u0623\u0643\u0628\u0631 \u0646\u0633\u0628\u0629 \u0646\u0633\u064a\u0627\u0646 \u062a\u0643\u0648\u0646 \u0641\u064a \u0627\u0644\u0633\u0627\u0639\u0627\u062a \u0627\u0644\u0623\u0648\u0644\u0649 \u0628\u0639\u062f \u0627\u0644\u062a\u0639\u0644\u0645\u060c \u062b\u0645 \u064a\u062a\u0646\u0627\u0642\u0635.",u.N)
B.W8=s(["\u0627\u0644\u0642\u062f\u0631\u0629\u060c \u0627\u0644\u062c\u0647\u062f\u060c \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u0645\u0647\u0645\u0629\u060c \u0648\u0627\u0644\u062d\u0638","\u0644\u0648\u0646 \u0627\u0644\u0623\u062f\u0648\u0627\u062a \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629 \u0641\u0642\u0637","\u0633\u0627\u0639\u0627\u062a \u0627\u0644\u0646\u0648\u0645 \u0641\u0642\u0637","\u062d\u062c\u0645 \u0627\u0644\u0642\u0633\u0645 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.akD=new A.e("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0625\u0633\u0646\u0627\u062f (L\u2019attribution) \u062a\u0641\u0633\u0631 \u0646\u062c\u0627\u062d \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0641\u0634\u0644\u0647 \u0628\u0625\u0631\u062c\u0627\u0639\u0647 \u0625\u0644\u0649 \u0623\u0633\u0628\u0627\u0628 \u0645\u0646\u0647\u0627:",B.W8,0,"\u0641\u064a\u0628\u0631 \u0648\u064a\u0631\u0646\u0631: \u0627\u0644\u0625\u0633\u0646\u0627\u062f\u0627\u062a (\u0627\u0644\u0642\u062f\u0631\u0629/\u0627\u0644\u062c\u0647\u062f/\u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u0645\u0647\u0645\u0629/\u0627\u0644\u062d\u0638) \u062a\u0624\u062b\u0631 \u0639\u0644\u0649 \u0627\u0644\u062f\u0627\u0641\u0639\u064a\u0629 \u0648\u0627\u0644\u062a\u062d\u0635\u064a\u0644 \u0644\u0627\u062d\u0642\u0627\u064b.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.a4p=s(["\u0631\u0641\u0639 \u0627\u0644\u0623\u062f\u0627\u0621 \u062f\u0627\u0626\u0645\u0627\u064b","\u0625\u0639\u0627\u0642\u0629 \u0627\u0644\u0623\u062f\u0627\u0621 \u0625\u0630\u0627 \u0627\u0631\u062a\u0641\u0639 \u0628\u0634\u0643\u0644 \u0645\u0641\u0631\u0637","\u0645\u062d\u0648 \u0623\u062b\u0631 \u0627\u0644\u062a\u0639\u0644\u0645 \u0646\u0647\u0627\u0626\u064a\u0627\u064b","\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u062d\u0633\u064a\u0629 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.anD=new A.e("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u0627\u0644\u0642\u0644\u0642 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646\u064a \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u064a\u0639\u0645\u0644 \u0639\u0627\u062f\u0629 \u0639\u0644\u0649:",B.a4p,1,"\u0642\u0644\u0642 \u0642\u0644\u064a\u0644 \u064a\u0645\u0643\u0646 \u0623\u0646 \u064a\u062d\u0641\u0632\u060c \u0644\u0643\u0646 \u0627\u0644\u0642\u0644\u0642 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646\u064a \u0627\u0644\u0645\u0641\u0631\u0637 \u064a\u0639\u0637\u0644 \u0627\u0644\u0627\u0633\u062a\u0631\u062c\u0627\u0639 \u0648\u0627\u0644\u0623\u062f\u0627\u0621 \u062e\u0644\u0627\u0644 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.a5s=s(["\u062b\u0628\u0627\u062a \u0627\u0644\u0646\u062a\u0627\u0626\u062c \u0639\u0646\u062f \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631","\u0623\u0646 \u064a\u0642\u064a\u0633 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0641\u0639\u0644\u0627\u064b \u0645\u0627 \u0648\u064f\u0636\u0639 \u0644\u0642\u064a\u0627\u0633\u0647","\u0633\u0631\u0639\u0629 \u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0633\u0626\u0644\u0629","\u0637\u0648\u0644 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asA=new A.e("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u0641\u064a \u0627\u0644\u0642\u064a\u0627\u0633 \u0627\u0644\u0646\u0641\u0633\u064a\u060c \u064a\u0642\u0635\u062f \u0628\u0640\xab\u0627\u0644\u0635\u062f\u0642\xbb:",B.a5s,1,"\u0627\u0644\u0635\u062f\u0642: \u0627\u0644\u0645\u0644\u0627\u0621\u0645\u0629 \u0628\u064a\u0646 \u0645\u0627 \u064a\u0642\u064a\u0633\u0647 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0648\u0628\u064a\u0646 \u0627\u0644\u063a\u0631\u0636 \u0627\u0644\u0630\u064a \u0648\u064f\u0636\u0639 \u0644\u0647\u061b \u0623\u0645\u0627 \xab\u0627\u0644\u062b\u0628\u0627\u062a\xbb \u0641\u0647\u0648 \u0627\u0633\u062a\u0642\u0631\u0627\u0631 \u0627\u0644\u0646\u062a\u0627\u0626\u062c.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb \u2014 \u0635 18")
B.Wk=s(["\u062a\u0633\u0627\u0639\u062f \u062e\u0628\u0631\u0629 \u0633\u0627\u0628\u0642\u0629 \u0639\u0644\u0649 \u062a\u0639\u0644\u0645 \u062c\u062f\u064a\u062f","\u062a\u0639\u064a\u0642 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0623\u0648 \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u062c\u062f\u064a\u062f","\u0644\u0627 \u062a\u0648\u062c\u062f \u0623\u064a \u0639\u0644\u0627\u0642\u0629 \u0628\u064a\u0646 \u0627\u0644\u062a\u0639\u0644\u0645\u064a\u0646","\u064a\u062a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645 \u062f\u0648\u0646 \u0623\u062e\u0637\u0627\u0621","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.al7=new A.e("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u0646\u0642\u0644 \u0623\u062b\u0631 \u0627\u0644\u062a\u0639\u0644\u0645 \u064a\u0643\u0648\u0646 \u0633\u0627\u0644\u0628\u0627\u064b \u0639\u0646\u062f\u0645\u0627:",B.Wk,1,"\u0627\u0644\u0646\u0642\u0644 \u0627\u0644\u0633\u0627\u0644\u0628: \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0633\u0627\u0628\u0642 \u064a\u0639\u064a\u0642 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u062c\u062f\u064a\u062f (\u0643\u062a\u0623\u062b\u064a\u0631 \u0627\u0644\u0639\u0627\u062f\u0627\u062a \u0627\u0644\u0642\u062f\u064a\u0645\u0629)\u060c \u0648\u0627\u0644\u0646\u0642\u0644 \u0627\u0644\u0645\u0648\u062c\u0628 \u064a\u064a\u0633\u0631\u0647.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.a7M=s(["\u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0639\u0642\u0644\u064a \xf7 \u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0632\u0645\u0646\u064a \xd7 100","\u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0632\u0645\u0646\u064a \xf7 \u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0639\u0642\u0644\u064a \xd7 100","\u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0639\u0642\u0644\u064a \xd7 \u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0632\u0645\u0646\u064a \xf7 100","\u0639\u062f\u062f \u0627\u0644\u0625\u062c\u0627\u0628\u0627\u062a \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \xd7 10","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqw=new A.e("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u062d\u0627\u0635\u0644 \u0627\u0644\u0630\u0643\u0627\u0621 (IQ) \u064a\u064f\u062d\u0633\u0628 \u0639\u0627\u062f\u0629 \u0648\u0641\u0642 \u0627\u0644\u0639\u0644\u0627\u0642\u0629:",B.a7M,0,"\u062d\u0627\u0635\u0644 \u0627\u0644\u0630\u0643\u0627\u0621 = (\u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0639\u0642\u0644\u064a/\u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0632\u0645\u0646\u064a)\xd7100\u061b \u0627\u0644\u0642\u064a\u0645\u0629 100 \u062a\u0645\u062b\u0644 \u0627\u0644\u0645\u062a\u0648\u0633\u0637\u060c \u0648\u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u0637\u0628\u064a\u0639\u064a \u062d\u0648\u0644\u0647\u0627.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.a2W=s(["\u0627\u0644\u062a\u0647\u062f\u064a\u062f \u0627\u0644\u0645\u0633\u062a\u0645\u0631 \u0648\u0627\u0644\u0635\u0631\u0627\u0645\u0629","\u0627\u0644\u0623\u0645\u0627\u0646 \u0627\u0644\u0646\u0641\u0633\u064a\u060c \u0627\u0644\u062a\u0642\u062f\u064a\u0631\u060c \u0648\u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0645\u0641\u062a\u0648\u062d","\u0627\u0644\u0644\u0627\u0645\u0628\u0627\u0644\u0627\u0629 \u0628\u0639\u0644\u0627\u0642\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646","\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0639\u0644\u0649 \u0627\u0644\u0639\u0642\u0627\u0628 \u0627\u0644\u062c\u0645\u0627\u0639\u064a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqK=new A.e("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u0645\u0646 \u0623\u0647\u0645 \u062e\u0635\u0627\u0626\u0635 \u0627\u0644\u0645\u0646\u0627\u062e \u0627\u0644\u0635\u0641\u064a \u0627\u0644\u0645\u0624\u062b\u0631 \u0625\u064a\u062c\u0627\u0628\u064a\u0627\u064b \u0641\u064a \u0627\u0644\u062a\u0639\u0644\u0645:",B.a2W,1,"\u0645\u0646\u0627\u062e \u0622\u0645\u0646 \u062a\u0642\u062f\u064a\u0631\u064a \u062a\u0648\u0627\u0635\u0644\u064a \u064a\u0631\u0641\u0639 \u062f\u0627\u0641\u0639\u064a\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0648\u064a\u0642\u0644\u0644 \u0627\u0644\u0642\u0644\u0642 \u0648\u064a\u0639\u0632\u0632 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0648\u0627\u0644\u062a\u062d\u0635\u064a\u0644.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.abT=s(["\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0648\u0627\u0644\u0641\u0631\u0648\u0642 \u0627\u0644\u0641\u0631\u062f\u064a\u0629 \u0641\u064a \u0627\u0644\u062a\u0639\u0644\u0645","\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0644\u063a\u0627\u062a \u0627\u0644\u0623\u062c\u0646\u0628\u064a\u0629 \u0641\u0642\u0637","\u062a\u0643\u0648\u064a\u0646 \u0627\u0644\u0623\u0637\u0631 \u0627\u0644\u0625\u062f\u0627\u0631\u064a\u0629 \u0641\u0642\u0637","\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0645\u0642\u0631\u0631\u0627\u062a \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asq=new A.e("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0644\u0627\u062c\u064a (\u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0639\u0644\u0627\u062c\u064a\u0629) \u064a\u0647\u062a\u0645 \u0623\u0633\u0627\u0633\u0627\u064b \u0628\u0640:",B.abT,0,"\u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0639\u0644\u0627\u062c\u064a\u0629 \u0623\u0646\u0634\u0637\u0629 \u062f\u0627\u0639\u0645\u0629 \u062a\u0633\u062a\u0647\u062f\u0641 \u0627\u0644\u0645\u062a\u0639\u062b\u0631\u064a\u0646 \u0628\u0639\u062f \u0627\u0644\u062a\u0634\u062e\u064a\u0635 \u0644\u0633\u062f \u0627\u0644\u062b\u063a\u0631\u0627\u062a \u0648\u0625\u0639\u0627\u062f\u0629 \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb \u2014 \u0635 59")
B.a0j=s(["\u0627\u0644\u0648\u0631\u0627\u062b\u0629 \u0648\u062d\u062f\u0647\u0627 \u062f\u0648\u0646 \u0627\u0644\u0645\u062d\u064a\u0637","\u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0648\u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0644\u063a\u0648\u064a \u0645\u0639 \u0627\u0644\u0645\u062d\u064a\u0637","\u0646\u0648\u0639 \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0641\u0642\u0637","\u0639\u062f\u062f \u0633\u0627\u0639\u0627\u062a \u0627\u0644\u0646\u0648\u0645","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
