B.aau=s(["\u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a.","\u0627\u0644\u0643\u0641\u0627\u064a\u0629.","\u0627\u0644\u0645\u0647\u0627\u0631\u0629 \u0627\u0644\u0628\u0633\u064a\u0637\u0629.","\u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a \u0627\u0644\u0642\u0628\u064a\u0644\u064a\u0629."],t.s)
B.alv=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0630\u064a \u064a\u064f\u0639\u0628\u0631 \u0639\u0646 "\u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062a\u0639\u0628\u0626\u0629 \u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u062f\u0645\u062c\u0629 \u0645\u0646 \u0627\u0644\u0645\u0648\u0627\u0631\u062f \u0644\u062d\u0644 \u0648\u0636\u0639\u064a\u0629 \u0645\u0634\u0643\u0644\u0629" \u0647\u0648:',B.aau,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0643\u0641\u0627\u064a\u0629.",u.C)
B.a_o=s(["\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0645\u0634\u0631\u0648\u0639.","\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629.","\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0639\u0642\u062f.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.apj=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u064a \u062a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0645\u0631\u0627\u0639\u0627\u0629 \u0627\u0644\u0641\u0631\u0648\u0642 \u0627\u0644\u0641\u0631\u062f\u064a\u0629 \u0628\u064a\u0646 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0648\u062a\u0646\u0648\u064a\u0639 \u0645\u0633\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u062f\u0627\u062e\u0644 \u0627\u0644\u0641\u0635\u0644 \u0647\u064a:",B.a_o,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629.",u.C)
B.a70=s(["\u0633\u0644\u0648\u0643 \u0633\u0644\u0628\u064a \u064a\u062c\u0628 \u0645\u0639\u0627\u0642\u0628\u0629 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0639\u0644\u064a\u0647 \u0641\u0648\u0631\u0627\u064b.","\u0645\u0624\u0634\u0631 \u0625\u064a\u062c\u0627\u0628\u064a \u064a\u0646\u0628\u063a\u064a \u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0647 \u0643\u0634\u0627\u0647\u062f \u0639\u0644\u0649 \u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629.","\u062f\u0644\u064a\u0644 \u0642\u0627\u0637\u0639 \u0639\u0644\u0649 \u0639\u062f\u0645 \u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u0645\u0642\u0631\u0631 \u0627\u0644\u062f\u0631\u0627\u0633\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aq4=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u0639\u062a\u0628\u0631 \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062e\u0637\u0623 \u0623\u0646 \u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0645\u062a\u0639\u0644\u0645:",B.a70,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u0624\u0634\u0631 \u0625\u064a\u062c\u0627\u0628\u064a \u064a\u0646\u0628\u063a\u064a \u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0647 \u0643\u0634\u0627\u0647\u062f \u0639\u0644\u0649 \u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629.",u.C)
B.aaw=s(["\u0633\u0647\u0644\u0629 \u0648\u0628\u0633\u064a\u0637\u0629 \u064a\u0645\u0643\u0646 \u062d\u0644\u0647\u0627 \u0645\u0628\u0627\u0634\u0631\u0629 \u062f\u0648\u0646 \u062a\u0641\u0643\u064a\u0631.","\u0645\u0639\u0642\u062f\u0629 \u0648\u0630\u0627\u062a \u0645\u0639\u0646\u0649 \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u062a\u062a\u062d\u062f\u0649 \u0642\u062f\u0631\u0627\u062a\u0647 \u0648\u062a\u0633\u062a\u062f\u0639 \u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u0648\u0627\u0631\u062f.","\u0645\u0633\u062a\u062d\u064a\u0644\u0629 \u0627\u0644\u062d\u0644 \u0644\u0628\u064a\u0627\u0646 \u0636\u0639\u0641 \u0627\u0644\u0645\u062a\u0639\u0644\u0645.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ao0=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0645\u0646 \u0634\u0631\u0648\u0637 "\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0634\u0643\u0644\u0629" \u0627\u0644\u0641\u0639\u0627\u0644\u0629 \u0641\u064a \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0628\u0627\u0644\u0643\u0641\u0627\u064a\u0627\u062a \u0623\u0646 \u062a\u0643\u0648\u0646:',B.aaw,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u0639\u0642\u062f\u0629 \u0648\u0630\u0627\u062a \u0645\u0639\u0646\u0649 \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u062a\u062a\u062d\u062f\u0649 \u0642\u062f\u0631\u0627\u062a\u0647 \u0648\u062a\u0633\u062a\u062f\u0639 \u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u0645\u0648\u0627\u0631\u062f.",u.C)
B.Zr=s(["\u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629 \u2190 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u2190 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0648\u062c\u0647\u0629.","\u0627\u0644\u0646\u0645\u0630\u062c\u0629 (\u0627\u0644\u0634\u0631\u062d \u0627\u0644\u0645\u0628\u0627\u0634\u0631) \u2190 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0648\u062c\u0647\u0629 \u2190 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a \u2190 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u2190 \u0627\u0644\u062a\u0645\u0647\u064a\u062f.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.auu=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0623\u0633\u0644\u0648\u0628 "\u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0635\u0631\u064a\u062d" (Explicit Teaching) \u064a\u062a\u0643\u0648\u0646 \u0628\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0645\u0646 \u062e\u0637\u0648\u0627\u062a:',B.Zr,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0646\u0645\u0630\u062c\u0629 (\u0627\u0644\u0634\u0631\u062d \u0627\u0644\u0645\u0628\u0627\u0634\u0631) \u2190 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0648\u062c\u0647\u0629 \u2190 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629.",u.C)
B.a3N=s(["\u062a\u0635\u0646\u064a\u0641 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u062d\u0633\u0628 \u0627\u0644\u0633\u0646 \u0648\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0627\u0644\u0646\u0638\u0627\u0645\u064a.","\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0641\u0639\u0644\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0641\u064a \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u062a\u0643\u064a\u064a\u0641 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0641\u0642 \u0645\u0633\u062a\u0648\u0627\u0647 \u0627\u0644\u062d\u0642\u064a\u0642\u064a.","\u0625\u0644\u063a\u0627\u0621 \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0625\u0642\u0635\u0627\u0626\u0647\u0627.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aur=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u0639\u062a\u0645\u062f \u0645\u0642\u0627\u0631\u0628\u0629 (TaRL) - \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0648\u0641\u0642 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0646\u0627\u0633\u0628 \u0628\u0627\u0644\u0623\u0633\u0627\u0633 \u0639\u0644\u0649:",B.a3N,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0641\u0639\u0644\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0641\u064a \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u062a\u0643\u064a\u064a\u0641 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0641\u0642 \u0645\u0633\u062a\u0648\u0627\u0647 \u0627\u0644\u062d\u0642\u064a\u0642\u064a.",u.C)
B.YG=s(["\u0642\u0636\u0627\u0621 \u0648\u0642\u062a \u0627\u0644\u0641\u0631\u0627\u063a \u062f\u0648\u0646 \u0623\u0647\u062f\u0627\u0641 \u062a\u0631\u0628\u0648\u064a\u0629.","\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u062a\u0639\u0644\u0645 \u0625\u0644\u0649 \u0623\u0646\u0634\u0637\u0629 \u0645\u0645\u062a\u0639\u0629 \u0647\u0627\u062f\u0641\u0629 \u062a\u0646\u0645\u064a \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0630\u0647\u0646\u064a\u0629 \u0648\u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u064a\u0629.","\u0625\u0639\u0641\u0627\u0621 \u0627\u0644\u0645\u062f\u0631\u0633 \u0645\u0646 \u062a\u062d\u0636\u064a\u0631 \u0627\u0644\u062c\u0630\u0627\u0630\u0627\u062a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.atH=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0644\u0639\u0628 \u062a\u0647\u062f\u0641 \u0641\u064a \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0641\u0635\u0644\u064a\u0629 \u0625\u0644\u0649:",B.YG,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u062a\u0639\u0644\u0645 \u0625\u0644\u0649 \u0623\u0646\u0634\u0637\u0629 \u0645\u0645\u062a\u0639\u0629 \u0647\u0627\u062f\u0641\u0629 \u062a\u0646\u0645\u064a \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0630\u0647\u0646\u064a\u0629 \u0648\u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u064a\u0629.",u.C)
B.abm=s(["\u0627\u0644\u0639\u0642\u062f \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a.","\u0627\u0644\u0646\u0642\u0644 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a (Transposition didactique).","\u0627\u0644\u0639\u0627\u0626\u0642 \u0627\u0644\u0627\u0628\u0633\u062a\u0645\u0648\u0644\u0648\u062c\u064a.","\u0627\u0644\u062a\u0645\u062b\u0644 \u0627\u0644\u0645\u0639\u0631\u0641\u064a."],t.s)
