B.abt=s(["\u0645\u0634\u0643\u0644\u0629 \u0641\u064a \u0627\u0644\u0625\u0636\u0627\u0621\u0629 \u0623\u0648 \u0627\u0644\u0637\u0627\u0648\u0644\u0627\u062a \u062f\u0627\u062e\u0644 \u0627\u0644\u062d\u062c\u0631\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629.","\u0635\u0639\u0648\u0628\u0629 \u0623\u0648 \u0645\u0641\u0647\u0648\u0645 \u062e\u0627\u0637\u0626 \u064a\u0639\u062a\u0631\u0636 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645 \u0646\u062a\u064a\u062c\u0629 \u0646\u0645\u0637 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0623\u0648 \u0637\u0628\u064a\u0639\u0629 \u0627\u0644\u0645\u0641\u0647\u0648\u0645.","\u063a\u064a\u0627\u0628 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0639\u0646 \u0627\u0644\u062d\u0635\u0635 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqA=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0639\u0627\u0626\u0642 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u0647\u0648:",B.abt,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0635\u0639\u0648\u0628\u0629 \u0623\u0648 \u0645\u0641\u0647\u0648\u0645 \u062e\u0627\u0637\u0626 \u064a\u0639\u062a\u0631\u0636 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645 \u0646\u062a\u064a\u062c\u0629 \u0646\u0645\u0637 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0623\u0648 \u0637\u0628\u064a\u0639\u0629 \u0627\u0644\u0645\u0641\u0647\u0648\u0645.",u.C)
B.a4m=s(["\u062f\u0631\u0627\u0633\u0629 \u0627\u0644\u062d\u0627\u0644\u0629.","\u0627\u0644\u0639\u0635\u0641 \u0627\u0644\u0630\u0647\u0646\u064a (Brainstorming).","\u0644\u0639\u0628 \u0627\u0644\u0623\u062f\u0648\u0627\u0631.","\u0627\u0644\u0641\u064a\u0644\u064a\u0628\u0633 6\xd76."],t.s)
B.aqo=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u0642\u0646\u064a\u0629 \u0627\u0644\u062a\u0646\u0634\u064a\u0637 \u0627\u0644\u062a\u064a \u062a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u0625\u0646\u062a\u0627\u062c \u0623\u0641\u0643\u0627\u0631 \u0645\u062a\u0639\u062f\u062f\u0629 \u0648\u062d\u0631\u0629 \u062d\u0648\u0644 \u0645\u0648\u0636\u0648\u0639 \u0645\u0639\u064a\u0646 \u062f\u0648\u0646 \u0646\u0642\u062f \u0645\u0628\u0643\u0631 \u062a\u0633\u0645\u0649:",B.a4m,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0639\u0635\u0641 \u0627\u0644\u0630\u0647\u0646\u064a (Brainstorming).",u.C)
B.a3t=s(["\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u062f\u0631\u0648\u0633 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0628\u0646\u0641\u0633 \u0627\u0644\u0643\u064a\u0641\u064a\u0629.","\u0627\u0644\u0631\u0628\u0637 \u0648\u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0629 \u0628\u064a\u0646 \u0645\u0639\u0627\u0631\u0641 \u0648\u0645\u0647\u0627\u0631\u0627\u062a \u0633\u0627\u0628\u0642\u0629 \u0648\u0645\u062e\u062a\u0644\u0641\u0629 \u0648\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0647\u0627 \u0628\u0634\u0643\u0644 \u0645\u062f\u0645\u062c.","\u062d\u0641\u0638 \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0648\u0643\u062a\u0627\u0628\u062a\u0647\u0627 \u0641\u064a \u062f\u0641\u062a\u0631 \u0627\u0644\u0645\u0644\u062e\u0635\u0627\u062a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.ami=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u0648\u0644\u064a\u0641 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a (Int\xe9gration des acquis) \u064a\u0639\u0646\u064a:",B.a3t,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0631\u0628\u0637 \u0648\u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0629 \u0628\u064a\u0646 \u0645\u0639\u0627\u0631\u0641 \u0648\u0645\u0647\u0627\u0631\u0627\u062a \u0633\u0627\u0628\u0642\u0629 \u0648\u0645\u062e\u062a\u0644\u0641\u0629 \u0648\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0647\u0627 \u0628\u0634\u0643\u0644 \u0645\u062f\u0645\u062c.",u.C)
B.ab5=s(["\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a/\u0627\u0644\u062e\u062a\u0627\u0645\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aku=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u062d\u0648\u0631 \u0627\u0644\u062e\u0627\u0645\u0633: \u0627\u0644\u062a\u0642\u0648\u064a\u0645\u060c \u0627\u0644\u062f\u0639\u0645\u060c \u0648\u0627\u0644\u062a\u0634\u0631\u064a\u0639\u0627\u062a \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0630\u064a \u064a\u064f\u0646\u062c\u0632 \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0646\u0629 \u0623\u0648 \u0628\u062f\u0627\u064a\u0629 \u0648\u062d\u062f\u0629 \u062f\u0631\u0627\u0633\u064a\u0629 \u0644\u0631\u0635\u062f \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0627\u0644\u0642\u0628\u0644\u064a\u0629 \u064a\u064f\u0633\u0645\u0649:",B.ab5,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a.",u.C)
B.W0=s(["\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0625\u0634\u0647\u0627\u062f\u064a.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0648\u0642\u0639\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.arM=new A.e("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0645\u0633\u062a\u0645\u0631 \u0627\u0644\u0630\u064a \u064a\u0631\u0627\u0641\u0642 \u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0628\u0647\u062f\u0641 \u0631\u0635\u062f \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0627\u0644\u0641\u0648\u0631\u064a\u0629 \u0648\u062a\u0639\u062f\u064a\u0644 \u0645\u0633\u0627\u0631 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u064a\u064f\u0633\u0645\u0649:",B.W0,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a.",u.C)
B.a8E=s(["\u0627\u0644\u0645\u0641\u062a\u0634 \u0628\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0645\u062f\u0631\u0633.","\u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0628\u062a\u0642\u0648\u064a\u0645 \u0625\u0646\u062c\u0627\u0632 \u0632\u0645\u064a\u0644\u0647 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0645\u0639\u0627\u064a\u064a\u0631 \u0648\u0634\u0628\u0643\u0629 \u0645\u062d\u062f\u062f\u0629.","\u0627\u0644\u0645\u062f\u0631\u0633 \u0628\u062a\u0642\u0648\u064a\u0645 \u0646\u0641\u0633\u0647 \u0630\u0627\u062a\u064a\u0627\u064b.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
