B.Xa=s(["\u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0627\u0644\u0645\u062c\u0631\u062f \u0648\u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0641\u0631\u0636 \u0627\u0644\u0641\u0631\u0636\u064a\u0627\u062a.","\u0638\u0647\u0648\u0631 \u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0627\u0644\u0631\u0645\u0632\u064a \u0648\u0627\u0644\u0644\u063a\u0629 \u0628\u0634\u0643\u0644 \u0645\u0643\u062b\u0641 \u0645\u0639 \u0627\u0644\u062a\u0645\u0631\u0643\u0632 \u062d\u0648\u0644 \u0627\u0644\u0630\u0627\u062a.","\u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0627\u0644\u0643\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u0635\u0646\u064a\u0641 \u0648\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0623\u0634\u064a\u0627\u0621 \u0645\u0627\u062f\u064a\u0629.","\u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0644\u0644\u0627\u0646\u0639\u0643\u0627\u0633\u0627\u062a \u0627\u0644\u062d\u0633\u064a\u0629 \u0648\u0627\u0644\u062d\u0631\u0643\u064a\u0629 \u0641\u0642\u0637."],t.s)
B.amI=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'2. \u062d\u0633\u0628 \u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0645\u0639\u0631\u0641\u064a \u0644\u0640 "\u062c\u0627\u0646 \u0628\u064a\u0627\u062c\u064a\u0647"\u060c \u062a\u062a\u0645\u064a\u0632 \u0645\u0631\u062d\u0644\u0629 "\u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0645\u0627\u062f\u064a\u0629/\u0627\u0644\u0645\u0644\u0645\u0648\u0633\u0629" (\u0645\u0646 7 \u0625\u0644\u0649 11 \u0633\u0646\u0629) \u0628\u0640:',B.Xa,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0627\u0644\u0643\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u0635\u0646\u064a\u0641 \u0648\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0623\u0634\u064a\u0627\u0621 \u0645\u0627\u062f\u064a\u0629.",u.C)
B.Y3=s(["\u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0641\u0639\u0644\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0645\u062d\u062a\u0645\u0644 \u062a\u062d\u062a \u0625\u0634\u0631\u0627\u0641 \u0648\u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u0634\u062f \u0623\u0648 \u0623\u0642\u0631\u0627\u0646 \u0623\u0643\u062b\u0631 \u0642\u062f\u0631\u0629.","\u0627\u0644\u0630\u0643\u0627\u0621\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u062f\u062f\u0629 \u063a\u064a\u0631 \u0627\u0644\u0645\u0643\u062a\u0634\u0641\u0629 \u0628\u0639\u062f \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645.","\u0627\u0644\u0641\u0627\u0631\u0642 \u0627\u0644\u062d\u0627\u0635\u0644 \u0628\u064a\u0646 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0627\u0644\u062d\u0642\u064a\u0642\u064a \u0648\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0635\u0648\u0631\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645.","\u0642\u062f\u0631\u0629 \u0627\u0644\u0637\u0641\u0644 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0645\u0633\u062a\u0642\u0644 \u062f\u0648\u0646 \u0623\u064a \u0645\u0633\u0627\u0639\u062f\u0629 \u062e\u0627\u0631\u062c\u064a\u0629."],t.s)
B.apP=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'3. \u0645\u0641\u0647\u0648\u0645 "\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0642\u0631\u064a\u0628" (ZPD) \u0644\u0644\u0628\u0627\u062d\u062b "\u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a" \u064a\u0639\u0628\u0631 \u0639\u0646:',B.Y3,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0641\u0639\u0644\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0645\u062d\u062a\u0645\u0644 \u062a\u062d\u062a \u0625\u0634\u0631\u0627\u0641 \u0648\u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u0634\u062f \u0623\u0648 \u0623\u0642\u0631\u0627\u0646 \u0623\u0643\u062b\u0631 \u0642\u062f\u0631\u0629.",u.C)
B.a1v=s(["\u0648\u0636\u0639\u064a\u0629 \u062a\u062d\u062a\u0648\u064a \u0639\u0644\u0649 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u062e\u0627\u0637\u0626\u0629 \u0644\u0625\u0631\u0628\u0627\u0643 \u0627\u0644\u0645\u062a\u0639\u0644\u0645.","\u0648\u0636\u0639\u064a\u0629 \u062a\u062d\u062f\u062b \u0639\u0627\u0626\u0642\u0627\u064b \u0645\u0639\u0631\u0641\u064a\u0627\u064b \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u064a\u062c\u0639\u0644\u0647 \u064a\u0634\u0639\u0631 \u0628\u0639\u062f\u0645 \u0643\u0641\u0627\u064a\u0629 \u0645\u0648\u0627\u0631\u062f\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0644\u0644\u062d\u0644.","\u0645\u0633\u0623\u0644\u0629 \u062d\u0633\u0627\u0628\u064a\u0629 \u0628\u0633\u064a\u0637\u0629 \u062a\u062a\u0637\u0644\u0628 \u062a\u0637\u0628\u064a\u0642 \u0642\u0627\u0639\u062f\u0629 \u0645\u0628\u0627\u0634\u0631\u0629.","\u0648\u0636\u0639\u064a\u0629 \u0645\u0639\u0642\u062f\u0629 \u062c\u062f\u0627\u064b \u062a\u0633\u062a\u0648\u062c\u0628 \u062a\u062f\u062e\u0644 \u0627\u0644\u0645\u062f\u0631\u0633 \u0644\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062d\u0644 \u0645\u0628\u0627\u0634\u0631\u0629."],t.s)
B.al8=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'4. \u0641\u064a \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u062d\u0644 \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a\u060c \u062a\u064f\u0639\u0631\u0641 "\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0634\u0643\u0644\u0629 \u0627\u0644\u0645\u0634\u0648\u0634\u0629/\u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629" \u0628\u0623\u0646\u0647\u0627:',B.a1v,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0648\u0636\u0639\u064a\u0629 \u062a\u062d\u062f\u062b \u0639\u0627\u0626\u0642\u0627\u064b \u0645\u0639\u0631\u0641\u064a\u0627\u064b \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u064a\u062c\u0639\u0644\u0647 \u064a\u0634\u0639\u0631 \u0628\u0639\u062f\u0645 \u0643\u0641\u0627\u064a\u0629 \u0645\u0648\u0627\u0631\u062f\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0644\u0644\u062d\u0644.",u.C)
B.VN=s(["\u062a\u0642\u0648\u064a\u0645 \u064a\u0647\u062f\u0641 \u0625\u0644\u0649 \u0645\u0646\u062d \u062f\u0631\u062c\u0627\u062a \u0648\u0625\u062d\u062f\u0627\u062b \u062a\u0635\u0646\u064a\u0641 \u0646\u0647\u0627\u0626\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646.","\u062a\u0642\u0648\u064a\u0645 \u062a\u0634\u062e\u064a\u0635\u064a \u064a\u062c\u0631\u0649 \u0641\u0642\u0637 \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629.","\u062a\u0642\u0648\u064a\u0645 \u0645\u062f\u0645\u062c \u0641\u064a \u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u064a\u0647\u062f\u0641 \u0625\u0644\u0649 \u0631\u0635\u062f \u0627\u0644\u0635\u0639\u0648\u0628\u0627\u062a \u0648\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a \u0641\u0648\u0631\u064a\u0627\u064b.","\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0643\u0644 \u0633\u0644\u0643 \u062f\u0631\u0627\u0633\u064a."],t.s)
B.ana=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'5. \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 "\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a" (\xc9valuation formative) \u0641\u064a \u0623\u062f\u0628\u064a\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062d\u062f\u064a\u062b\u0629:',B.VN,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0642\u0648\u064a\u0645 \u0645\u062f\u0645\u062c \u0641\u064a \u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u064a\u0647\u062f\u0641 \u0625\u0644\u0649 \u0631\u0635\u062f \u0627\u0644\u0635\u0639\u0648\u0628\u0627\u062a \u0648\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a \u0641\u0648\u0631\u064a\u0627\u064b.",u.C)
