B.alQ=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'17. \u064a\u064f\u0639\u0631\u0641 "\u0627\u0644\u062e\u0637\u0623" \u0641\u064a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0628\u0623\u0646\u0647:',B.VU,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0646\u0642\u0637\u0629 \u0627\u0646\u0637\u0644\u0627\u0642 \u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0645\u0624\u0634\u0631 \u0644\u062f\u0631\u0627\u0633\u0629 \u062a\u0645\u062b\u0644\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0633\u0644\u064a\u0645\u0629.",u.C)
B.abI=s(["\u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0641\u064a \u0627\u0644\u0639\u0642\u0648\u0628\u0627\u062a \u0627\u0644\u0645\u0645\u0643\u0646\u0629 \u0644\u0644\u062a\u0644\u0627\u0645\u0630\u0629 \u0627\u0644\u0645\u0634\u0627\u063a\u0628\u064a\u0646.","\u0627\u0644\u0645\u0633\u0627\u0621\u0644\u0629 \u0627\u0644\u0630\u0627\u062a\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0645\u0631\u0629 \u0644\u0644\u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0627\u0644\u0641\u0635\u0644\u064a\u0629 \u0648\u062a\u062d\u0644\u064a\u0644\u0647\u0627 \u0644\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0623\u062f\u0627\u0621 \u0648\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a.","\u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0641\u064a \u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u062a\u062e\u0637\u064a\u0637\u0627\u062a \u0627\u0644\u064a\u0648\u0645\u064a\u0629 \u0641\u0642\u0637.","\u0645\u0646\u0627\u0642\u0634\u0629 \u0627\u0644\u0642\u0636\u0627\u064a\u0627 \u0627\u0644\u0625\u062f\u0627\u0631\u064a\u0629 \u0641\u064a \u0645\u062c\u0627\u0644\u0633 \u0627\u0644\u0645\u0624\u0633\u0633\u0629."],t.s)
B.aoq=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'18. \u0645\u0645\u0627\u0631\u0633\u0629 "\u0627\u0644\u062a\u0641\u0643\u0631" (La pratique r\xe9flexive) \u0639\u0646\u062f \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u062a\u0639\u0646\u064a:',B.abI,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u0633\u0627\u0621\u0644\u0629 \u0627\u0644\u0630\u0627\u062a\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0645\u0631\u0629 \u0644\u0644\u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0627\u0644\u0641\u0635\u0644\u064a\u0629 \u0648\u062a\u062d\u0644\u064a\u0644\u0647\u0627 \u0644\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0623\u062f\u0627\u0621 \u0648\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a.",u.C)
B.Xi=s(["\u0625\u0639\u0641\u0627\u0621 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0648\u0636\u0639\u064a\u0629 \u0625\u0639\u0627\u0642\u0629 \u0645\u0646 \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629.","\u062a\u0639\u062f\u064a\u0644\u0627\u062a \u0648\u062a\u0643\u064a\u0641\u0627\u062a \u0641\u064a \u0627\u0644\u0637\u0631\u0642 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0648\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0637\u0631\u0642 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0644\u062a\u0646\u0627\u0633\u0628 \u0630\u0648\u064a \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u062f\u0648\u0646 \u0625\u062e\u0644\u0627\u0644 \u0628\u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0639\u0644\u0645\u064a\u0629.","\u0639\u0632\u0644 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0630\u0648\u064a \u0627\u0644\u0625\u0639\u0627\u0642\u0629 \u0641\u064a \u0645\u062f\u0627\u0631\u0633 \u062e\u0627\u0635\u0629 \u062f\u0627\u0626\u0645\u0627\u064b.","\u062e\u0641\u0636 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646 \u0644\u062c\u0645\u064a\u0639 \u062a\u0644\u0627\u0645\u064a\u0630 \u0627\u0644\u0641\u0635\u0644."],t.s)
B.arf=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'19. \u0641\u064a \u0633\u064a\u0627\u0642 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u062f\u0627\u0645\u062c\u0629\u060c \u062a\u064f\u0639\u0631\u0641 "\u0627\u0644\u062a\u0643\u064a\u064a\u0641\u0627\u062a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629" \u0628\u0623\u0646\u0647\u0627:',B.Xi,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0639\u062f\u064a\u0644\u0627\u062a \u0648\u062a\u0643\u064a\u0641\u0627\u062a \u0641\u064a \u0627\u0644\u0637\u0631\u0642 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0648\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0637\u0631\u0642 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0644\u062a\u0646\u0627\u0633\u0628 \u0630\u0648\u064a \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u062f\u0648\u0646 \u0625\u062e\u0644\u0627\u0644 \u0628\u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0639\u0644\u0645\u064a\u0629.",u.C)
B.adg=s(["\u0627\u0644\u0633\u0644\u0648\u0643 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u0627\u0644\u0642\u0627\u0628\u0644 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u0642\u064a\u0627\u0633.","\u0627\u0644\u0645\u0634\u0627\u0639\u0631\u060c \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0630\u0627\u062a\u064a\u0629\u060c \u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0630\u0627\u062a\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0639\u0644\u0627\u0642\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064a\u0629 \u0627\u0644\u0625\u064a\u062c\u0627\u0628\u064a\u0629.","\u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u062d\u0633\u0627\u0628\u064a\u0629 \u0648\u0627\u0644\u0645\u0646\u0637\u0642 \u0627\u0644\u0635\u0648\u0631\u064a \u0641\u0642\u0637.","\u0627\u0644\u0628\u0631\u0645\u062c\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0627\u0644\u0639\u0635\u0628\u064a\u0629 \u0648\u062a\u0637\u0628\u064a\u0642\u0627\u062a\u0647\u0627 \u0627\u0644\u0641\u0646\u064a\u0629."],t.s)
B.are=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"20. \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0641\u064a\u0646\u0648\u0645\u064a\u0646\u0648\u0644\u0648\u062c\u064a\u0629 \u0623\u0648 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064a\u0629 (\u0645\u062b\u0644 \u0631\u0624\u064a\u0629 \u0643\u0627\u0631\u0644 \u0631\u0648\u062c\u0631\u0632) \u062a\u0631\u0643\u0632 \u0623\u0633\u0627\u0633\u0627\u064b \u0639\u0644\u0649:",B.adg,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u0634\u0627\u0639\u0631\u060c \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0630\u0627\u062a\u064a\u0629\u060c \u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0630\u0627\u062a\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0639\u0644\u0627\u0642\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064a\u0629 \u0627\u0644\u0625\u064a\u062c\u0627\u0628\u064a\u0629.",u.C)
B.a0i=s(["\u0628\u062d\u062b \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0644\u0641\u0631\u062f\u064a \u0639\u0646 \u0627\u0644\u062d\u0644\u0648\u0644 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u062a\u0645\u062b\u0644\u062a\u0647.","\u0625\u0636\u0641\u0627\u0621 \u0627\u0644\u0635\u0628\u063a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0636\u0648\u0639\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0631\u064a\u0641 \u0648\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0628\u0648\u0627\u0633\u0637\u0629 \u0627\u0644\u0645\u062f\u0631\u0633.","\u062a\u0628\u0627\u062f\u0644 \u0627\u0644\u0631\u0645\u0648\u0632 \u0648\u0627\u0644\u0635\u064a\u0627\u063a\u0627\u062a \u0628\u064a\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0627\u062a.","\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062d\u062c\u062c \u0648\u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0644\u0644\u062a\u0631\u062c\u064a\u062d \u0628\u064a\u0646 \u0627\u0644\u0635\u064a\u0627\u063a\u0627\u062a."],t.s)
B.arC=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'21. \u0648\u0641\u0642 \u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0644\u0640 "\u063a\u064a \u0628\u0631\u0648\u0633\u0648" (Guy Brousseau)\u060c \u0645\u0631\u062d\u0644\u0629 "\u0627\u0644\u0645\u0623\u0633\u0633\u0629" ( Institutionnalisation ) \u062a\u0639\u0646\u064a:',B.a0i,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0625\u0636\u0641\u0627\u0621 \u0627\u0644\u0635\u0628\u063a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0636\u0648\u0639\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0631\u064a\u0641 \u0648\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0628\u0648\u0627\u0633\u0637\u0629 \u0627\u0644\u0645\u062f\u0631\u0633.",u.C)
B.a6B=s(["\u0627\u0644\u0628\u062f\u0621 \u0645\u0628\u0627\u0634\u0631\u0629 \u0628\u0627\u0644\u0631\u0645\u0648\u0632 \u0648\u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u062b\u0645 \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0644\u0644\u0631\u0633\u0648\u0645 \u0627\u0644\u0628\u064a\u0627\u0646\u064a\u0629.","\u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0648\u0644\u0629 \u0628\u0627\u0644\u064a\u062f \u0644\u0644\u0648\u0633\u0627\u0626\u0644 \u0648\u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u0627\u062f\u064a\u0629\u060c \u062b\u0645 \u0634\u0628\u0647 \u0627\u0644\u0645\u062d\u0633\u0648\u0633 (\u0627\u0644\u0635\u0648\u0631 \u0648\u0627\u0644\u0631\u0633\u0648\u0645)\u060c \u0648\u0635\u0648\u0644\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u0645\u062c\u0631\u062f (\u0627\u0644\u0631\u0645\u0648\u0632).","\u0627\u0644\u0627\u0642\u062a\u0635\u0627\u0631 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u0627\u0626\u0644 \u0627\u0644\u0644\u0641\u0638\u064a\u0629 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629 \u0628\u0627\u0644\u0646\u0635.","\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062d\u0627\u0633\u0628\u0629 \u0627\u0644\u0622\u0644\u064a\u0629 \u0641\u064a \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u0635\u0635."],t.s)
B.anL=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'22. \u0641\u064a \u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0628\u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629\u060c \u0627\u0644\u0645\u0628\u062f\u0623 \u0627\u0644\u0645\u0646\u0647\u062c\u064a \u0627\u0644\u0645\u0646\u0627\u062f\u064a \u0628\u0640 "\u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 \u0645\u0646 \u0627\u0644\u0645\u062d\u0633\u0648\u0633 \u0625\u0644\u0649 \u0627\u0644\u0645\u062c\u0631\u062f" \u064a\u0642\u062a\u0636\u064a:',B.a6B,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0648\u0644\u0629 \u0628\u0627\u0644\u064a\u062f \u0644\u0644\u0648\u0633\u0627\u0626\u0644 \u0648\u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u0627\u062f\u064a\u0629\u060c \u062b\u0645 \u0634\u0628\u0647 \u0627\u0644\u0645\u062d\u0633\u0648\u0633 (\u0627\u0644\u0635\u0648\u0631 \u0648\u0627\u0644\u0631\u0633\u0648\u0645)\u060c \u0648\u0635\u0648\u0644\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u0645\u062c\u0631\u062f (\u0627\u0644\u0631\u0645\u0648\u0632).",u.C)
B.aee=s(["\u0623\u0633\u0628\u0648\u0639\u064a \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0643\u0644 \u0648\u062d\u062f\u0629 \u062f\u0631\u0627\u0633\u064a\u0629.","\u064a\u0648\u0645\u064a \u0648\u0645\u0646\u062a\u0638\u0645 \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0643\u0644 \u062d\u0635\u0629 \u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0644\u0645\u062f\u0629 5 \u0625\u0644\u0649 10 \u062f\u0642\u0627\u0626\u0642.","\u0627\u062e\u062a\u064a\u0627\u0631\u064a \u0648\u062d\u0633\u0628 \u0631\u063a\u0628\u0629 \u0627\u0644\u0623\u0633\u062a\u0627\u0630.","\u0634\u0647\u0631\u064a \u062e\u0644\u0627\u0644 \u0641\u062a\u0631\u0627\u062a \u0627\u0644\u062f\u0639\u0645 \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645."],t.s)
B.apB=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'23. "\u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0630\u0647\u0646\u064a" \u0627\u0644\u0645\u0639\u062a\u0645\u062f \u0641\u064a \u0627\u0644\u0645\u0646\u0647\u0627\u062c \u0627\u0644\u0645\u0646\u0642\u062d \u0644\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0628\u0627\u0644\u0645\u063a\u0631\u0628 \u064a\u064f\u0645\u0627\u0631\u0633 \u0628\u0634\u0643\u0644:',B.aee,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u064a\u0648\u0645\u064a \u0648\u0645\u0646\u062a\u0638\u0645 \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0643\u0644 \u062d\u0635\u0629 \u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0644\u0645\u062f\u0629 5 \u0625\u0644\u0649 10 \u062f\u0642\u0627\u0626\u0642.",u.C)
B.a4q=s(["\u0627\u0644\u0645\u0623\u0633\u0633\u0629   leftarrow  \u0627\u0644\u0635\u064a\u0627\u063a\u0629   leftarrow  \u0627\u0644\u0641\u0639\u0644   leftarrow  \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629.","\u0627\u0644\u0641\u0639\u0644   leftarrow  \u0627\u0644\u0635\u064a\u0627\u063a\u0629   leftarrow  \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629   leftarrow  \u0627\u0644\u0645\u0623\u0633\u0633\u0629   leftarrow  \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631.","\u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629   leftarrow  \u0627\u0644\u0641\u0639\u0644   leftarrow  \u0627\u0644\u0645\u0623\u0633\u0633\u0629   leftarrow  \u0627\u0644\u0635\u064a\u0627\u063a\u0629.","\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631   leftarrow  \u0627\u0644\u0645\u0623\u0633\u0633\u0629   leftarrow  \u0627\u0644\u0641\u0639\u0644   leftarrow  \u0627\u0644\u0635\u064a\u0627\u063a\u0629."],t.s)
B.arI=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'24. \u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0635\u062d\u064a\u062d \u0644\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u062d\u0633\u0628 "\u0628\u0631\u0648\u0633\u0648" \u0647\u0648:',B.a4q,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0641\u0639\u0644   leftarrow  \u0627\u0644\u0635\u064a\u0627\u063a\u0629   leftarrow  \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629   leftarrow  \u0627\u0644\u0645\u0623\u0633\u0633\u0629   leftarrow  \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631.",u.C)
B.a96=s(["\u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u062a\u062e\u0635\u0635\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629.","\u0627\u0644\u0645\u062c\u0627\u0644\u0627\u062a \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0627\u0644\u0645\u0642\u0631\u0631\u0629 \u0641\u064a \u0627\u0644\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u0645\u0631\u0629 \u0627\u0644\u0625\u0634\u0647\u0627\u062f\u064a\u0629.","\u063a\u064a\u0631 \u0627\u0644\u0645\u0639\u0646\u064a\u0629 \u0628\u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629.","\u0627\u0644\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 \u0648\u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0627\u0644\u0639\u0631\u0636\u0627\u0646\u064a\u0629 (\u0627\u0644\u062d\u0633 \u0627\u0644\u0645\u0642\u0627\u0637\u0639\u064a/\u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u062d\u064a\u0627\u062a\u064a\u0629)."],t.s)
B.aqN=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"25. \u0627\u0644\u0646\u0638\u0627\u0641\u0629\u060c \u0627\u0644\u0628\u064a\u0626\u0629\u060c \u0627\u0644\u0635\u062d\u0629\u060c \u0648\u0627\u0644\u0645\u0627\u0644\u064a\u0629 \u0647\u064a \u0645\u0648\u0627\u0636\u064a\u0639 \u062a\u062f\u0631\u062c \u0641\u064a \u0645\u0646\u0647\u0627\u062c \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u0628\u0627\u0644\u0645\u063a\u0631\u0628 \u0636\u0645\u0646:",B.a96,3,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 \u0648\u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0627\u0644\u0639\u0631\u0636\u0627\u0646\u064a\u0629 (\u0627\u0644\u062d\u0633 \u0627\u0644\u0645\u0642\u0627\u0637\u0639\u064a/\u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u062d\u064a\u0627\u062a\u064a\u0629).",u.C)
B.abK=s(["\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u0646\u0635\u064a\u0629 \u0627\u0644\u062a\u062d\u0644\u064a\u0644\u064a\u0629 \u0627\u0644\u0645\u0639\u0642\u062f\u0629.","\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u0635\u0648\u062a\u064a\u0629 (\u0627\u0644\u0645\u0643\u0648\u0646 \u0627\u0644\u0645\u0642\u0637\u0639\u064a: \u0627\u0644\u0648\u0639\u064a \u0627\u0644\u0635\u0648\u062a\u064a\u060c \u0627\u0644\u0631\u0628\u0637 \u0628\u064a\u0646 \u0627\u0644\u0635\u0648\u062a \u0648\u0627\u0644\u0631\u0645\u0632...).","\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u064a\u0629 \u0627\u0644\u0634\u0627\u0645\u0644\u0629 \u062f\u0648\u0646 \u062a\u0641\u0643\u064a\u0643 \u0627\u0644\u0643\u0644\u0645\u0627\u062a.","\u062a\u0631\u062c\u0645\u0629 \u0627\u0644\u0646\u0635\u0648\u0635 \u0648\u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0627\u0644\u0623\u0641\u0643\u0627\u0631 \u0627\u0644\u0639\u0627\u0645\u0629 \u0641\u0642\u0637."],t.s)
B.ar3=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'26. \u0645\u0643\u0648\u0646 "\u0627\u0644\u0642\u0631\u0627\u0621\u0629" \u0641\u064a \u0627\u0644\u0633\u0644\u0643 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u064a\u0646\u0637\u0644\u0642 \u0641\u064a \u0633\u0646\u0648\u0627\u062a\u0647 \u0627\u0644\u0623\u0648\u0644\u0649 (\u0627\u0644\u0623\u0648\u0644 \u0648\u0627\u0644\u062b\u0627\u0646\u064a) \u0645\u0646 \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629:',B.abK,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u0635\u0648\u062a\u064a\u0629 (\u0627\u0644\u0645\u0643\u0648\u0646 \u0627\u0644\u0645\u0642\u0637\u0639\u064a: \u0627\u0644\u0648\u0639\u064a \u0627\u0644\u0635\u0648\u062a\u064a\u060c \u0627\u0644\u0631\u0628\u0637 \u0628\u064a\u0646 \u0627\u0644\u0635\u0648\u062a \u0648\u0627\u0644\u0631\u0645\u0632...).",u.C)
B.ab_=s(["\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642   leftarrow  \u062a\u062f\u0648\u064a\u0646 \u0627\u0644\u0646\u062a\u0627\u0626\u062c   leftarrow  \u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u0641\u0631\u0636\u064a\u0627\u062a   leftarrow  \u0635\u064a\u0627\u063a\u0629 \u0633\u0624\u0627\u0644 \u0627\u0644\u062a\u0642\u0635\u064a.","\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642   leftarrow  \u062a\u0645\u0644\u0643 \u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0648\u0635\u064a\u0627\u063a\u0629 \u0633\u0624\u0627\u0644 \u0627\u0644\u062a\u0642\u0635\u064a   leftarrow  \u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u0641\u0631\u0636\u064a\u0627\u062a   leftarrow  \u0627\u062e\u062a\u0628\u0627\u0631 \u0627\u0644\u0641\u0631\u0636\u064a\u0627\u062a   leftarrow  \u0627\u0644\u0646\u062a\u0627\u0626\u062c \u0648\u0627\u0644\u062a\u0648\u062b\u064a\u0642   leftarrow  \u0627\u0644\u062a\u0639\u0645\u064a\u0645 \u0648\u0627\u0644\u0627\u0633\u062a\u0646\u062a\u0627\u062c.","\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062e\u0644\u0627\u0635\u0629   leftarrow  \u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u062a\u062c\u0631\u0628\u0629   leftarrow  \u0637\u0631\u062d \u0627\u0644\u0633\u0624\u0627\u0644.","\u0627\u0644\u062d\u0641\u0638 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0644\u0644\u0645\u0641\u0627\u0647\u064a\u0645   leftarrow  \u062d\u0644 \u0627\u0644\u0645\u0633\u0627\u0626\u0644."],t.s)
B.at6=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"27. \u0627\u0644\u0646\u0647\u062c \u0627\u0644\u062a\u0642\u0635\u064a (D\xe9marche d'investigation) \u0627\u0644\u0645\u0639\u062a\u0645\u062f \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a \u064a\u062a\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u062e\u0637\u0648\u0627\u062a \u0627\u0644\u0645\u0631\u062a\u0628\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629:",B.ab_,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642   leftarrow  \u062a\u0645\u0644\u0643 \u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0648\u0635\u064a\u0627\u063a\u0629 \u0633\u0624\u0627\u0644 \u0627\u0644\u062a\u0642\u0635\u064a   leftarrow  \u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u0641\u0631\u0636\u064a\u0627\u062a   leftarrow  \u0627\u062e\u062a\u0628\u0627\u0631 \u0627\u0644\u0641\u0631\u0636\u064a\u0627\u062a   leftarrow  \u0627\u0644\u0646\u062a\u0627\u0626\u062c \u0648\u0627\u0644\u062a\u0648\u062b\u064a\u0642   leftarrow  \u0627\u0644\u062a\u0639\u0645\u064a\u0645 \u0648\u0627\u0644\u0627\u0633\u062a\u0646\u062a\u0627\u062c.",u.C)
B.aaB=s(["\u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0625\u0634\u0647\u0627\u062f\u064a\u0629 \u0641\u0642\u0637.","\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629 \u0627\u0644\u0645\u0628\u0643\u0631\u0629 \u0648\u0627\u0644\u0648\u0633\u0637\u0649 \u0644\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0633\u0631\u0639\u0629 \u0648\u0627\u0644\u062f\u0642\u0629 \u0648\u0627\u0644\u0636\u0628\u0637.","\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0634\u0641\u0647\u064a \u062f\u0648\u0646 \u0627\u0644\u062d\u0627\u062c\u0629 \u0625\u0644\u0649 \u0646\u0635 \u0645\u0643\u062a\u0648\u0628.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0644\u0644\u0633\u0644\u0643 \u0627\u0644\u062b\u0646\u0648\u064a."],t.s)
B.auj=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"28. \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u062b\u0646\u0627\u0626\u064a\u0629\u060c \u0648\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0646\u0645\u0627\u0630\u062c\u060c \u0648\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0647\u0645\u0633\u064a\u0629\u060c \u062a\u064f\u0639\u062a\u0628\u0631 \u0645\u0646 \u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0637\u0644\u0627\u0642\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0641\u064a:",B.aaB,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629 \u0627\u0644\u0645\u0628\u0643\u0631\u0629 \u0648\u0627\u0644\u0648\u0633\u0637\u0649 \u0644\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0633\u0631\u0639\u0629 \u0648\u0627\u0644\u062f\u0642\u0629 \u0648\u0627\u0644\u0636\u0628\u0637.",u.C)
B.a2_=s(["\u062a\u0631\u0643 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u064a\u0643\u062a\u0634\u0641 \u0643\u0644 \u0634\u064a\u0621 \u0628\u0646\u0641\u0633\u0647 \u062f\u0648\u0646 \u062a\u0642\u062f\u064a\u0645 \u0623\u064a \u0645\u062b\u0627\u0644.","\u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u0645\u062f\u0631\u0633 \u0644\u0644\u0645\u0647\u0645\u0629 \u0623\u0645 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0645\u0639 \u0634\u0631\u062d \u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0628\u0635\u0648\u062a \u0639\u0627\u0644\u064d \u0644\u064a\u062d\u062a\u0630\u0648\u0627 \u0628\u0647.","\u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u062a\u0644\u0627\u0645\u0630\u0629 \u0646\u0645\u0627\u0630\u062c \u0645\u062c\u0633\u0645\u0629 \u0645\u0646 \u0627\u0644\u0628\u0644\u0627\u0633\u062a\u064a\u0643 \u0641\u0642\u0637.","\u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646 \u0628\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u062f\u062f\u0629."],t.s)
B.atA=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"29. \u0627\u0644\u0646\u0645\u0630\u062c\u0629 (Modelling) \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0627\u062a \u062a\u0639\u0646\u064a:",B.a2_,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u0645\u062f\u0631\u0633 \u0644\u0644\u0645\u0647\u0645\u0629 \u0623\u0645 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0645\u0639 \u0634\u0631\u062d \u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0628\u0635\u0648\u062a \u0639\u0627\u0644\u064d \u0644\u064a\u062d\u062a\u0630\u0648\u0627 \u0628\u0647.",u.C)
B.a3e=s(["\u0627\u062e\u062a\u0628\u0627\u0631 \u062d\u0641\u0638 \u0627\u0644\u062a\u0639\u0627\u0631\u064a\u0641 \u0648\u0627\u0644\u0645\u0635\u0637\u0644\u062d\u0627\u062a.","\u0639\u0628\u0626\u0629 \u0648\u0645\u0632\u062c \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0648\u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0644\u0644\u0648\u062d\u062f\u0629 \u0644\u062d\u0644 \u0648\u0636\u0639\u064a\u0627\u062a \u0645\u0634\u0643\u0644\u0629 \u0645\u0631\u0643\u0628\u0629.","\u062a\u0642\u062f\u064a\u0645 \u062f\u0631\u0648\u0633 \u062c\u062f\u064a\u062f\u0629 \u0625\u0636\u0627\u0641\u064a\u0629 \u062e\u0627\u0631\u062c \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c.","\u0627\u0633\u062a\u0631\u0627\u062d\u0629 \u0648\u0627\u0633\u062a\u062c\u0645\u0627\u0645 \u0644\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646."],t.s)
B.aqT=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'30. \u062a\u0647\u062f\u0641 "\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0648\u0644\u064a\u0641\u064a\u0629" (Activit\xe9s d\'int\xe9gration) \u0641\u064a \u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u0641 \u0625\u0644\u0649:',B.a3e,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0639\u0628\u0626\u0629 \u0648\u0645\u0632\u062c \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0648\u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0644\u0644\u0648\u062d\u062f\u0629 \u0644\u062d\u0644 \u0648\u0636\u0639\u064a\u0627\u062a \u0645\u0634\u0643\u0644\u0629 \u0645\u0631\u0643\u0628\u0629.",u.C)
B.Z5=s(["\u0646\u0642\u0644 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0645\u0646 \u0645\u0633\u062a\u0648\u0649 \u062f\u0631\u0627\u0633\u064a \u0625\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0623\u0639\u0644\u0649.","\u0646\u0642\u0644 \u0627\u0644\u0623\u062b\u0627\u062b \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0628\u064a\u0646 \u0627\u0644\u0641\u0635\u0648\u0644.",'\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u062a\u062d\u0648\u064a\u0644 \u0648\u0627\u0644\u062a\u0643\u064a\u0641 \u0627\u0644\u062a\u064a \u062a\u062e\u0636\u0639 \u0644\u0647\u0627 "\u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u0629" \u0644\u062a\u0628\u0633\u064a\u0637\u0647\u0627 \u0648\u062a\u0635\u0628\u062d "\u0645\u0639\u0631\u0641\u0629 \u0635\u0627\u0644\u062d\u0629 \u0644\u0644\u062a\u062f\u0631\u064a\u0633".',"\u0646\u0642\u0644 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0645\u0646 \u0645\u0624\u0633\u0633\u0629 \u0625\u0644\u0649 \u0623\u062e\u0631\u0649."],t.s)
