B.aqE=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'37. \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0639\u0627\u0626\u0644\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 (\u0645\u062b\u0644: \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0628\u0639\u062f \u0627\u0644\u0642\u0631\u0627\u0621\u0629) \u062a\u0634\u0645\u0644 \u0641\u064a \u0645\u0631\u062d\u0644\u0629 "\u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629":',B.Zq,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0635\u0641\u062d \u0627\u0644\u0639\u0646\u0648\u0627\u0646\u060c \u0627\u0644\u0635\u0648\u0631\u060c \u0627\u0644\u062a\u0646\u0628\u0624 \u0628\u0645\u0648\u0636\u0648\u0639 \u0627\u0644\u0646\u0635\u060c \u0648\u0627\u0633\u062a\u062f\u0639\u0627\u0621 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0627\u0644\u0642\u0628\u0644\u064a\u0629.",u.C)
B.adC=s(["\u064a\u062a\u0623\u062e\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0639\u0646 \u0648\u0642\u062a \u0627\u0644\u062d\u0635\u0629.","\u064a\u0633\u062a\u0628\u062f\u0644 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0645\u0648\u0636\u0648\u0639 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0623\u0635\u0644\u064a \u0628\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0645\u0641\u0631\u0637 \u0639\u0644\u0649 \u0623\u062f\u0627\u0629 \u0623\u0648 \u0648\u0633\u064a\u0644\u0629 \u0645\u0633\u0627\u0639\u062f\u0629 \u062a\u062d\u0648\u0644 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u062b\u0627\u0646\u0648\u064a \u0625\u0644\u0649 \u0645\u0648\u0636\u0648\u0639 \u0623\u0633\u0627\u0633\u064a.","\u064a\u062e\u0631\u062c \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0625\u0644\u0649 \u0633\u0627\u062d\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062d\u0629.","\u064a\u0646\u0633\u0649 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0623\u062f\u0648\u0627\u062a\u0647 \u0627\u0644\u0645\u062f\u0631\u0633\u064a."],t.s)
B.amK=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'38. "\u0627\u0644\u0627\u0646\u0632\u0644\u0627\u0642 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a" (Glissement didactique) \u0647\u0648 \u0627\u0646\u062d\u0631\u0627\u0641 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u064a\u062d\u062f\u062b \u0639\u0646\u062f\u0645\u0627:',B.adC,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u064a\u0633\u062a\u0628\u062f\u0644 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0645\u0648\u0636\u0648\u0639 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0623\u0635\u0644\u064a \u0628\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0645\u0641\u0631\u0637 \u0639\u0644\u0649 \u0623\u062f\u0627\u0629 \u0623\u0648 \u0648\u0633\u064a\u0644\u0629 \u0645\u0633\u0627\u0639\u062f\u0629 \u062a\u062d\u0648\u0644 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u062b\u0627\u0646\u0648\u064a \u0625\u0644\u0649 \u0645\u0648\u0636\u0648\u0639 \u0623\u0633\u0627\u0633\u064a.",u.C)
