B.aq6=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0641\u064a \u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u0641 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639 5 \u0645\u0646 \u0627\u0644\u0648\u062d\u062f\u0629)\u060c \u062a\u062e\u0635\u0635 \u0627\u0644\u062d\u0635\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0644\u0640:",B.a4K,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0648\u0631\u0635\u062f \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0648\u062a\u0642\u064a\u064a\u0645 \u0645\u0627 \u062a\u062d\u0642\u0642 \u0645\u0646 \u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0648\u062d\u062f\u0629.",u.C)
B.acR=s(["\u0627\u0644\u062d\u0635\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0641\u0642\u0637 \u0645\u0646 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062e\u0627\u0645\u0633.","\u0627\u0644\u062d\u0635\u0635 \u0627\u0644\u0623\u0648\u0644\u0649 \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0648\u0627\u0644\u062b\u0627\u0644\u062b\u0629 \u062f\u0648\u0646 \u0627\u0644\u062d\u0627\u062c\u0629 \u0644\u062a\u0642\u0648\u064a\u0645.","\u0627\u0644\u062d\u0635\u062a\u064a\u0646 3 \u06485 \u0644\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0627\u0644\u0646\u0648\u0639\u064a\u0629 \u0628\u0639\u062f \u062a\u0641\u064a\u064a\u0626 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.alZ=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u062a\u0644\u062c\u0623 \u0627\u0644\u0623\u0633\u062a\u0627\u0630\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629 (Soutien cibl\xe9) \u0641\u064a \u062a\u062f\u0628\u064a\u0631 \u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u0641 \u062e\u0644\u0627\u0644:",B.acR,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062d\u0635\u062a\u064a\u0646 3 \u06485 \u0644\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0627\u0644\u0646\u0648\u0639\u064a\u0629 \u0628\u0639\u062f \u062a\u0641\u064a\u064a\u0626 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646.",u.C)
B.a07=s(["\u0635\u0646\u0639 \u0645\u062c\u0633\u0645\u0627\u062a \u0628\u0644\u0627\u0633\u062a\u064a\u0643\u064a\u0629 \u0648\u0643\u0631\u062a\u0648\u0646\u064a\u0629 \u0644\u0644\u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0641\u0636\u0627\u0626\u064a\u0629.","\u062a\u062d\u0648\u064a\u0644 \u0645\u0633\u0623\u0644\u0629 \u0623\u0648 \u0648\u0636\u0639\u064a\u0629 \u0648\u0627\u0642\u0639\u064a\u0629 \u0625\u0644\u0649 \u0646\u0645\u0648\u0630\u062c \u0623\u0648 \u0635\u064a\u0627\u063a\u0629 \u0631\u064a\u0627\u0636\u064a\u0629 \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0628\u0627\u0644\u0631\u0645\u0648\u0632.","\u062d\u0641\u0638 \u0635\u064a\u0627\u063a\u0627\u062a \u0627\u0644\u0642\u0648\u0627\u0646\u064a\u0646 \u0627\u0644\u062d\u0633\u0627\u0628\u064a\u0629 \u0648\u0627\u0633\u062a\u0638\u0647\u0627\u0631\u0647\u0627 \u0634\u0641\u0647\u064a\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.als=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u062a\u064f\u0639\u0631\u0641 "\u0627\u0644\u0645\u0648\u062f\u064a\u0644\u0629" \u0623\u0648 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629 (Mod\xe9lisation) \u0628\u0623\u0646\u0647\u0627:',B.a07,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u062d\u0648\u064a\u0644 \u0645\u0633\u0623\u0644\u0629 \u0623\u0648 \u0648\u0636\u0639\u064a\u0629 \u0648\u0627\u0642\u0639\u064a\u0629 \u0625\u0644\u0649 \u0646\u0645\u0648\u0630\u062c \u0623\u0648 \u0635\u064a\u0627\u063a\u0629 \u0631\u064a\u0627\u0636\u064a\u0629 \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0628\u0627\u0644\u0631\u0645\u0648\u0632.",u.C)
B.aac=s(["\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0643\u0627\u0645\u0644\u0627\u064b \u0648\u0628\u0634\u0643\u0644 \u0645\u0641\u0635\u0644 \u0641\u064a \u0645\u0633\u062a\u0648\u0649 \u062f\u0631\u0627\u0633\u064a \u0648\u0627\u062d\u062f \u062b\u0645 \u0625\u063a\u0644\u0627\u0642\u0647.","\u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0627\u0644\u0635\u0639\u0628\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u0648\u0627\u062a \u0627\u0644\u0623\u0648\u0644\u0649 \u0648\u062a\u0628\u0633\u064a\u0637\u0647\u0627 \u0641\u064a \u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0639\u0644\u064a\u0627.","\u0627\u0644\u0639\u0648\u062f\u0629 \u0644\u0646\u0641\u0633 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a \u0639\u0628\u0631 \u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0645\u062a\u062a\u0627\u0628\u0639\u0629 \u0645\u0639 \u0627\u0644\u062a\u0648\u0633\u0639 \u0648\u0627\u0644\u0639\u0645\u0642 \u0648\u0627\u0644\u062a\u062c\u0631\u064a\u062f \u0627\u0644\u062a\u062f\u0631\u064a\u062c\u064a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.atQ=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062d\u0644\u0632\u0648\u0646\u064a (Approche spiralaire) \u0644\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629 \u064a\u0642\u062a\u0636\u064a:",B.aac,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0639\u0648\u062f\u0629 \u0644\u0646\u0641\u0633 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a \u0639\u0628\u0631 \u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0645\u062a\u062a\u0627\u0628\u0639\u0629 \u0645\u0639 \u0627\u0644\u062a\u0648\u0633\u0639 \u0648\u0627\u0644\u0639\u0645\u0642 \u0648\u0627\u0644\u062a\u062c\u0631\u064a\u062f \u0627\u0644\u062a\u062f\u0631\u064a\u062c\u064a.",u.C)
B.a6n=s(["\u0625\u0644\u063a\u0627\u0621 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u0631\u0645\u0648\u0632 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629 \u0627\u0644\u0645\u0648\u062d\u062f\u0629.","\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0628\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0641\u0631\u0646\u0633\u064a\u0629 \u0648\u062a\u0648\u0638\u064a\u0641 \u0645\u0635\u0637\u0644\u062d\u0627\u062a\u0647\u0627 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a \u0645\u0639 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0644\u062a\u0647\u064a\u0626\u062a\u0647\u0645 \u0644\u0644\u0645\u0633\u062a\u0642\u0628\u0644.","\u062a\u0631\u062c\u0645\u0629 \u0627\u0644\u062d\u0635\u0635 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0643\u0644\u0645\u0629 \u0628\u0643\u0644\u0645\u0629 \u0634\u0641\u0647\u064a\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aml=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u0648\u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0627\u0644\u0644\u063a\u0648\u064a \u0641\u064a \u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u064a\u0647\u062f\u0641 \u0625\u0644\u0649:",B.a6n,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0628\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0641\u0631\u0646\u0633\u064a\u0629 \u0648\u062a\u0648\u0638\u064a\u0641 \u0645\u0635\u0637\u0644\u062d\u0627\u062a\u0647\u0627 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a \u0645\u0639 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0644\u062a\u0647\u064a\u0626\u062a\u0647\u0645 \u0644\u0644\u0645\u0633\u062a\u0642\u0628\u0644.",u.C)
B.ae0=s(["\u0645\u0646\u062d \u0646\u0642\u0627\u0637 \u0625\u0634\u0647\u0627\u062f\u064a\u0629 \u062a\u064f\u0633\u062c\u0644 \u0641\u064a \u0645\u0633\u0627\u0631 \u0644\u0644\u062a\u0644\u0627\u0645\u064a\u0630.","\u0631\u0635\u062f \u0627\u0644\u062c\u0627\u0647\u0632\u064a\u0629 \u0648\u0627\u0644\u062d\u062f\u0648\u062f \u0627\u0644\u0642\u0628\u0644\u064a\u0629 \u0644\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0648\u0628\u0646\u0627\u0621 \u062e\u0637\u0629 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0628\u0643\u0631\u0629.","\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0648\u0631\u0633\u0645 \u0633\u0644\u0645 \u0644\u0644\u062a\u0641\u0648\u0642 \u0648\u0627\u0644\u0631\u0633\u0648\u0628 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u062f\u0631\u0633\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.al1=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a \u0644\u0644\u0645\u0633\u062a\u0644\u0632\u0645\u0627\u062a \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629 \u064a\u0647\u062f\u0641 \u0623\u0633\u0627\u0633\u0627\u064b \u0625\u0644\u0649:",B.ae0,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0631\u0635\u062f \u0627\u0644\u062c\u0627\u0647\u0632\u064a\u0629 \u0648\u0627\u0644\u062d\u062f\u0648\u062f \u0627\u0644\u0642\u0628\u0644\u064a\u0629 \u0644\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0648\u0628\u0646\u0627\u0621 \u062e\u0637\u0629 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0628\u0643\u0631\u0629.",u.C)
B.a8X=s(["\u0648\u0636\u0639\u064a\u0629 \u0645\u0639\u0642\u062f\u0629 \u062c\u062f\u0627\u064b \u062a\u062a\u0637\u0644\u0628 \u0645\u0639\u0627\u0631\u0641 \u0644\u0645 \u064a\u062f\u0631\u0633\u0647\u0627 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0637\u0644\u0642\u0627\u064b.","\u062a\u0637\u0628\u064a\u0642 \u0645\u0628\u0627\u0634\u0631 \u0648\u062a\u0643\u0631\u0627\u0631\u064a \u0644\u0642\u0627\u0639\u062f\u0629 \u0631\u064a\u0627\u0636\u064a\u0629 \u062a\u0645 \u0634\u0631\u062d\u0647\u0627 \u0644\u0644\u062a\u0648.","\u0648\u0636\u0639\u064a\u0629 \u062a\u062d\u0645\u0644 \u0645\u0639\u0646\u0649 \u0648\u062a\u0636\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0623\u0645\u0627\u0645 \u0639\u0627\u0626\u0642 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u064a\u062a\u0637\u0644\u0628 \u0627\u0633\u062a\u062f\u0639\u0627\u0621 \u0648\u062a\u0648\u0644\u064a\u0641 \u0645\u0639\u0627\u0631\u0641\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0644\u062a\u062c\u0627\u0648\u0632\u0647.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqc=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u062a\u064f\u0639\u0631\u0641 "\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0633\u0623\u0644\u0629" (Situation-probl\xe8me) \u0627\u0644\u062c\u064a\u062f\u0629 \u0641\u064a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0628\u0640:',B.a8X,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0648\u0636\u0639\u064a\u0629 \u062a\u062d\u0645\u0644 \u0645\u0639\u0646\u0649 \u0648\u062a\u0636\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0623\u0645\u0627\u0645 \u0639\u0627\u0626\u0642 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u064a\u062a\u0637\u0644\u0628 \u0627\u0633\u062a\u062f\u0639\u0627\u0621 \u0648\u062a\u0648\u0644\u064a\u0641 \u0645\u0639\u0627\u0631\u0641\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0644\u062a\u062c\u0627\u0648\u0632\u0647.",u.C)
B.Vt=s(["\u0627\u0644\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0641\u064a \u062c\u062f\u0648\u0644 \u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a.","\u0645\u0642\u0627\u0631\u0646\u0629 \u0648\u0645\u0644\u0627 any \u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a \u0628\u0648\u0627\u0633\u0637\u0629 \u0648\u062d\u062f\u0627\u062a \u0627\u0639\u062a\u0628\u0627\u0637\u064a\u0629 \u0648\u062a\u0631\u0628\u064a\u0639\u0627\u062a (\u0627\u0644\u062a\u0628\u0644\u064a\u0637).","\u062d\u0633\u0627\u0628 \u062d\u062c\u0645 \u0627\u0644\u0645\u062c\u0633\u0645\u0627\u062a \u0627\u0644\u0642\u0627\u0626\u0645\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.at7=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0641\u064a \u062f\u0631\u0633 \u0642\u064a\u0627\u0633 \u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a \u0644\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639\u060c \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0630\u064a \u064a\u064f\u0628\u0646\u0649 \u0642\u0628\u0644 \u0627\u0644\u062a\u0642\u0646\u064a\u0629 \u0627\u0644\u0627\u0639\u062a\u064a\u0627\u062f\u064a\u0629 \u0644\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 ( S = L  times l ) \u0647\u0648:",B.Vt,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u0642\u0627\u0631\u0646\u0629 \u0648\u0645\u0644\u0627 any \u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a \u0628\u0648\u0627\u0633\u0637\u0629 \u0648\u062d\u062f\u0627\u062a \u0627\u0639\u062a\u0628\u0627\u0637\u064a\u0629 \u0648\u062a\u0631\u0628\u064a\u0639\u0627\u062a (\u0627\u0644\u062a\u0628\u0644\u064a\u0637).",u.C)
B.a2z=s(["\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u062d\u0627\u0633\u0628\u0629 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\u0629 \u062d\u0635\u0631\u0627\u064b.","\u0625\u062a\u0642\u0627\u0646 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u062a\u0641\u0643\u064a\u0643 \u0648\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0648\u062a\u0648\u0638\u064a\u0641 \u062e\u0627\u0635\u064a\u0627\u062a \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a (\u0627\u0644\u062a\u0648\u0632\u064a\u0639\u064a\u0629 \u0648\u0627\u0644\u062a\u0628\u0627\u062f\u0644\u064a\u0629).","\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0639\u0645\u0648\u062f\u064a\u0627\u064b \u0639\u0644\u0649 \u062f\u0641\u062a\u0631 \u0627\u0644\u062a\u0633\u0648\u064a\u062f \u0641\u0642\u0637.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.alA=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0633\u0631\u064a\u0639 (Calcul rapide) \u0643\u062c\u0632\u0621 \u0645\u0646 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0630\u0647\u0646\u064a \u064a\u0633\u062a\u0646\u062f \u0625\u0644\u0649:",B.a2z,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0625\u062a\u0642\u0627\u0646 \u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u062a\u0641\u0643\u064a\u0643 \u0648\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0648\u062a\u0648\u0638\u064a\u0641 \u062e\u0627\u0635\u064a\u0627\u062a \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a (\u0627\u0644\u062a\u0648\u0632\u064a\u0639\u064a\u0629 \u0648\u0627\u0644\u062a\u0628\u0627\u062f\u0644\u064a\u0629).",u.C)
B.acw=s(["\u0646\u0634\u0627\u0637 \u0627\u0644\u0645\u062f\u0631\u0633 \u0648\u0645\u0627 \u0633\u064a\u0634\u0631\u062d\u0647 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u0635\u0629.",'\u0648\u0635\u0641 \u0623\u0641\u0639\u0627\u0644 \u063a\u064a\u0631 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0645\u062b\u0644 "\u0623\u0646 \u064a\u0641\u0647\u0645 \u0627\u0644\u062a\u0644\u0645\u064a\u0630".',"\u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0644\u0642\u0627\u0628\u0644 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u0642\u064a\u0627\u0633 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 (\u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0642\u0627\u062f\u0631\u0627\u064b \u0639\u0644\u0649...).","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.atq=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a \u0627\u0644\u0645\u0635\u0627\u063a \u0628\u0634\u0643\u0644 \u0635\u062d\u064a\u062d \u064a\u062c\u0628 \u0623\u0646 \u064a\u0631\u0643\u0632 \u0639\u0644\u0649:",B.acw,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0644\u0642\u0627\u0628\u0644 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u0642\u064a\u0627\u0633 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 (\u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0642\u0627\u062f\u0631\u0627\u064b \u0639\u0644\u0649...).",u.C)
B.a0k=s(["\u0627\u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u0639\u062f\u062f\u064a \u0648\u0627\u0644\u062c\u062f\u0648\u0644 \u0648\u0627\u0644\u0645\u0643\u0639\u0628\u0627\u062a \u0648\u0627\u0644\u0635\u0641\u0627\u0626\u062d \u0648\u0627\u0644\u0642\u0637\u0639 \u0627\u0644\u0645\u0642\u0633\u0645\u0629 \u0625\u0644\u0649 \u0623\u0639\u0634\u0627\u0631 \u0648\u0623\u062c\u0632\u0627\u0621 \u0627\u0644\u0645\u0626\u0629.","\u0623\u0634\u0631\u0637\u0629 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0627\u0644\u0648\u062b\u0627\u0626\u0642\u064a\u0629 \u063a\u064a\u0631 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629.","\u0627\u0644\u0645\u0646\u0642\u0644\u0629 \u0648\u0627\u0644\u0645\u0632\u0648\u0627\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.atK=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u0648\u0633\u064a\u0644\u0629 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0627\u0644\u0623\u0643\u062b\u0631 \u0645\u0644\u0627\u0621\u0645\u0629 \u0644\u0628\u0646\u0627\u0621 \u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0639\u0634\u0631\u064a\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0631\u0627\u0628\u0639\u0629 \u0647\u064a:",B.a0k,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u0639\u062f\u062f\u064a \u0648\u0627\u0644\u062c\u062f\u0648\u0644 \u0648\u0627\u0644\u0645\u0643\u0639\u0628\u0627\u062a \u0648\u0627\u0644\u0635\u0641\u0627\u0626\u062d \u0648\u0627\u0644\u0642\u0637\u0639 \u0627\u0644\u0645\u0642\u0633\u0645\u0629 \u0625\u0644\u0649 \u0623\u0639\u0634\u0627\u0631 \u0648\u0623\u062c\u0632\u0627\u0621 \u0627\u0644\u0645\u0626\u0629.",u.C)
B.a3A=s(["\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0645\u0626\u0629 \u0648\u0627\u0644\u0646\u0633\u0628\u0629 \u0627\u0644\u0645\u0626\u0648\u064a\u0629 \u0627\u0644\u0645\u0639\u0642\u062f\u0629 \u0623\u0648\u0644\u0627\u064b.","\u062c\u062f\u0627\u0648\u0644 \u0627\u0644\u062a\u0646\u0627\u0633\u0628\u060c \u0627\u0644\u0645\u062e\u0637\u0637\u0627\u062a \u0627\u0644\u062e\u0637\u064a\u0629\u060c \u0648\u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u062a\u0646\u0627\u0633\u0628 \u0627\u0644\u0645\u0631\u0628\u0648\u0637 \u0628\u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0627\u0644\u0639\u062f\u062f\u064a\u0629.","\u062d\u0633\u0627\u0628 \u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u062f\u0627\u0626\u0631\u0629 \u0648\u062d\u062c\u0645 \u0627\u0644\u0643\u0631\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.asE=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0645\u0641\u0647\u0648\u0645 "\u0627\u0644\u062a\u0646\u0627\u0633\u0628\u064a\u0629" \u064a\u064f\u0628\u0646\u0649 \u0641\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629 \u0639\u0628\u0631 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0639\u0644\u0649:',B.a3A,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062c\u062f\u0627\u0648\u0644 \u0627\u0644\u062a\u0646\u0627\u0633\u0628\u060c \u0627\u0644\u0645\u062e\u0637\u0637\u0627\u062a \u0627\u0644\u062e\u0637\u064a\u0629\u060c \u0648\u0645\u0639\u0627\u0645\u0644 \u0627\u0644\u062a\u0646\u0627\u0633\u0628 \u0627\u0644\u0645\u0631\u0628\u0648\u0637 \u0628\u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0627\u0644\u0639\u062f\u062f\u064a\u0629.",u.C)
B.abM=s(["\u0627\u0644\u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u0628\u0627\u0644\u062e\u0644\u0641 \u0627\u0644\u0635\u0648\u0631\u064a \u0627\u0644\u0645\u062a\u0642\u062f\u0645.","\u0627\u0644\u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0626\u064a (\u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0645\u0646 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u0648\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0627\u0644\u0645\u0627\u062f\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u062a\u0639\u0645\u064a\u0645).","\u0627\u0644\u0628\u0631\u0647\u0627\u0646 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a \u0627\u0644\u0646\u0638\u0631\u064a \u0627\u0644\u0645\u062c\u0631\u062f.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aub=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u0627\u0644\u0631\u064a\u0627\u0636\u064a \u0627\u0644\u0645\u0639\u062a\u0645\u062f \u063a\u0627\u0644\u0628\u0627\u064b \u0641\u064a \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0647\u0648:",B.abM,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0626\u064a (\u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0645\u0646 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u0648\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0627\u0644\u0645\u0627\u062f\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u062a\u0639\u0645\u064a\u0645).",u.C)
B.a8p=s(["\u064a\u062d\u062a\u0648\u064a \u0639\u0644\u0649 \u0625\u062c\u0627\u0628\u0629 \u0648\u0627\u062d\u062f\u0629 \u0648\u0645\u0633\u0627\u0631 \u062d\u062a\u0645\u064a \u0645\u062d\u062f\u062f \u0645\u0633\u0628\u0642\u0627\u064b.","\u064a\u062a\u064a\u062d \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0648\u0637\u0631\u0642 \u062d\u0644 \u0645\u062a\u0639\u062f\u062f\u0629 \u0648\u0645\u062a\u0646\u0648\u0639\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0646\u0647\u0627\u064a\u0629.","\u0644\u0627 \u064a\u062a\u0637\u0644\u0628 \u0623\u064a \u062a\u0641\u0643\u064a\u0631 \u0623\u0648 \u0623\u062f\u0627\u0629 \u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.akx=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0645\u0641\u062a\u0648\u062d (Activit\xe9 ouverte) \u0641\u064a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0647\u0648 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0630\u064a:",B.a8p,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u064a\u062a\u064a\u062d \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0648\u0637\u0631\u0642 \u062d\u0644 \u0645\u062a\u0639\u062f\u062f\u0629 \u0648\u0645\u062a\u0646\u0648\u0639\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0646\u0647\u0627\u064a\u0629.",u.C)
B.a9w=s(["\u062a\u0648\u0642\u064a\u0639 \u0627\u0644\u062a\u0632\u0627\u0645 \u0645\u0639 \u0648\u0644\u064a \u0627\u0644\u0623\u0645\u0631 \u0628\u0627\u0644\u0645\u062d\u0643\u0645\u0629.","\u062a\u062d\u062f\u064a\u062f \u0648\u062a\u0648\u0636\u064a\u062d \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0648\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a \u0648\u0627\u0644\u0645\u0647\u0627\u0645 \u0627\u0644\u0632\u0645\u0627\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u0643\u0627\u0646\u064a\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u062f\u0631\u0633 \u0648\u0627\u0644\u0645\u062a\u0639\u0644\u0645.","\u0625\u062c\u0628\u0627\u0631 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0639\u0644\u0649 \u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0645\u0644\u062e\u0635 \u0628\u0635\u0631\u0627\u0645\u0629 \u062f\u0648\u0646 \u0645\u0646\u0627\u0642\u0634\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.an8=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0645\u0641\u0647\u0648\u0645 "\u0639\u0642\u062f \u0627\u0644\u062a\u0639\u0644\u0645" \u0623\u0648 "\u0627\u0644\u062a\u0639\u0627\u0642\u062f \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a" \u064a\u064f\u0641\u0639\u0644 \u0641\u064a \u0627\u0644\u0641\u0635\u0644 \u0645\u0646 \u062e\u0644\u0627\u0644:',B.a9w,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u062d\u062f\u064a\u062f \u0648\u062a\u0648\u0636\u064a\u062d \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0648\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a \u0648\u0627\u0644\u0645\u0647\u0627\u0645 \u0627\u0644\u0632\u0645\u0627\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u0643\u0627\u0646\u064a\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u062f\u0631\u0633 \u0648\u0627\u0644\u0645\u062a\u0639\u0644\u0645.",u.C)
B.Xn=s(["\u0645\u0631\u062d\u0644\u0629 \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0635\u0639\u0628\u0629 \u0641\u0642\u0637.","\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0630\u0647\u0646\u064a \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a \u0627\u0644\u0633\u0631\u064a\u0639 \u0644\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0634\u0627\u0626\u0639\u0629 \u0641\u0648\u0631\u064a\u0627\u064b.","\u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u0645\u0644\u062e\u0635\u0627\u062a \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629 \u0644\u062a\u0628\u0642\u0649 \u062f\u0627\u0626\u0645\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aoE=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u062a\u064f\u0639\u062a\u0628\u0631 \u0627\u0644\u0623\u0644\u0648\u0627\u062d (Ardoises) \u0623\u062f\u0627\u0629 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0631\u0626\u064a\u0633\u064a\u0629 \u062a\u0633\u062a\u0639\u0645\u0644 \u0628\u0643\u062b\u0631\u0629 \u0641\u064a:",B.Xn,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0630\u0647\u0646\u064a \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a \u0627\u0644\u0633\u0631\u064a\u0639 \u0644\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0634\u0627\u0626\u0639\u0629 \u0641\u0648\u0631\u064a\u0627\u064b.",u.C)
B.a6O=s(["\u0639\u0632\u0644 \u0627\u0644\u0645\u0639\u0627\u0631\u0641 \u0648\u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0648\u062c\u0639\u0644 \u0643\u0644 \u062f\u0631\u0633 \u0645\u0633\u062a\u0642\u0644 \u0628\u0630\u0627\u062a\u0647.","\u0631\u0628\u0637 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0648\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629 \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629 \u0648\u062a\u0637\u0628\u064a\u0642\u0647\u0627 \u0641\u064a \u0648\u0636\u0639\u064a\u0627\u062a \u0634\u0627\u0645\u0644\u0629 \u0648\u0645\u0631\u0643\u0628\u0629.","\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0641\u0631\u0648\u0636 \u0627\u0644\u0645\u0646\u0632\u0644\u064a\u0629 \u0648\u062a\u0635\u062d\u064a\u062d\u0647\u0627 \u0641\u0631\u062f\u064a\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
