B.app=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'62. \u064a\u062a\u0643\u0648\u0646 "\u0645\u062c\u0644\u0633 \u0627\u0644\u062a\u062f\u0628\u064a\u0631" \u0628\u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629 \u0628\u0631\u0626\u0627\u0633\u0629 \u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0648\u0639\u0636\u0648\u064a\u0629 \u0645\u0645\u062b\u0644\u064a\u0646 \u0639\u0646:',B.aeg,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0647\u064a\u0623\u0629 \u0627\u0644\u062a\u062f\u0631\u064a\u0633\u060c \u0627\u0644\u0623\u0637\u0631 \u0627\u0644\u0625\u062f\u0627\u0631\u064a\u0629\u060c \u0645\u0645\u062b\u0644 \u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u062a\u0631\u0627\u0628\u064a\u0629\u060c \u0648\u0631\u0626\u064a\u0633 \u062c\u0645\u0639\u064a\u0629 \u0623\u0645\u0647\u0627\u062a \u0648\u0622\u0628\u0627\u0621 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630.",u.C)
B.a26=s(["\u0623\u062b\u0646\u0627\u0621 \u0632\u0645\u0646 \u0648\u0645\u0643\u0627\u0646 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0641\u0639\u0644\u064a\u0629 \u0644\u0644\u0648\u0638\u064a\u0641\u0629 \u0623\u0648 \u0641\u064a \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0637\u0628\u064a\u0639\u064a \u0644\u0644\u0625\u064a\u0627\u0628 \u0648\u0627\u0644\u0630\u0647\u0627\u0628.","\u062e\u0644\u0627\u0644 \u0627\u0644\u0639\u0637\u0644 \u0627\u0644\u0635\u064a\u0641\u064a\u0629 \u0648\u0627\u0644\u0633\u0641\u0631 \u0627\u0644\u0634\u062e\u0635\u064a \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u063a\u0631\u0628.","\u0623\u064a\u0627\u0645 \u0639\u0637\u0644 \u0627\u0644\u0623\u0639\u064a\u0627\u062f \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0641\u064a \u0627\u0644\u0633\u0643\u0646 \u0627\u0644\u0634\u062e\u0635\u064a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.amG=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'63. "\u062d\u0648\u0627\u062f\u062b \u0627\u0644\u0634\u063a\u0644 \u0648\u0627\u0644\u062e\u062f\u0645\u0629" \u0627\u0644\u062a\u064a \u064a\u062a\u0639\u0631\u0636 \u0644\u0647\u0627 \u0627\u0644\u0645\u0648\u0638\u0641 \u0623\u0648 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u062a\u062d\u062a \u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u062a\u0646\u0638\u0645 \u0648\u062a\u063a\u0637\u064a\u0647\u0627 \u0627\u0644\u062f\u0648\u0644\u0629 \u0628\u0634\u0631\u0637 \u0623\u0646 \u062a\u0642\u0639:',B.a26,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0623\u062b\u0646\u0627\u0621 \u0632\u0645\u0646 \u0648\u0645\u0643\u0627\u0646 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0641\u0639\u0644\u064a\u0629 \u0644\u0644\u0648\u0638\u064a\u0641\u0629 \u0623\u0648 \u0641\u064a \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0637\u0628\u064a\u0639\u064a \u0644\u0644\u0625\u064a\u0627\u0628 \u0648\u0627\u0644\u0630\u0647\u0627\u0628.",u.C)
B.a32=s(["\u0627\u0644\u0639\u0632\u0644 \u0645\u0639 \u0627\u0644\u062d\u0631\u0645\u0627\u0646 \u0645\u0646 \u0627\u0644\u062a\u0642\u0627\u0639\u062f.","\u0627\u0644\u0625\u0646\u0630\u0627\u0631 \u0648\u0627\u0644\u062a\u0648\u0628\u064a\u062e.","\u0627\u0644\u0625\u062d\u0627\u0644\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0642\u0627\u0639\u062f \u0627\u0644\u062d\u062a\u0645\u064a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.anE=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'64. \u0627\u0644\u0639\u0642\u0648\u0628\u0629 \u0627\u0644\u062a\u0623\u062f\u064a\u0628\u064a\u0629 \u0627\u0644\u0645\u0646\u062a\u0645\u064a\u0629 \u0644\u0640 "\u0627\u0644\u062f\u0631\u062c\u0629 \u0627\u0644\u0623\u0648\u0644\u0649" \u062d\u0633\u0628 \u0627\u0644\u0648\u0638\u064a\u0641\u0629 \u0627\u0644\u0639\u0645\u0648\u0645\u064a\u0629 \u0628\u0627\u0644\u0645\u063a\u0631\u0628 \u0647\u064a:',B.a32,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0625\u0646\u0630\u0627\u0631 \u0648\u0627\u0644\u062a\u0648\u0628\u064a\u062e.",u.C)
B.a0o=s(["\u0646\u0634\u0631 \u0645\u0639\u0637\u064a\u0627\u062a \u0648\u0648\u062b\u0627\u0626\u0642 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0627\u0644\u0625\u062f\u0627\u0631\u064a\u0629 \u0648\u0627\u0644\u0646\u0641\u0633\u064a\u0629 \u0639\u0644\u0649 \u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u062a\u0648\u0627\u0635\u0644.","\u0639\u062f\u0645 \u0625\u0641\u0634\u0627\u0621 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0648\u0627\u0644\u0623\u0633\u0631\u0627\u0631 \u0627\u0644\u062a\u064a \u064a\u0637\u0644\u0639 \u0639\u0644\u064a\u0647\u0627 \u0628\u062d\u0643\u0645 \u0645\u0645\u0627\u0631\u0633\u062a\u0647 \u0627\u0644\u0645\u0647\u0646\u064a\u0629 \u0625\u0644\u0627 \u0628\u0631\u062e\u0635\u0629 \u0623\u0648 \u0648\u0627\u062c\u0628 \u0642\u0627\u0646\u0648\u0646\u064a.","\u0625\u0641\u0634\u0627\u0621 \u0627\u0644\u0645\u0639\u0637\u064a\u0627\u062a \u0644\u0644\u0639\u0645\u0648\u0645 \u0628\u0645\u062c\u0631\u062f \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0644\u0645\u0624\u0633\u0633\u0629 \u0623\u062e\u0631\u0649.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.apq=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'65. "\u0627\u0644\u0633\u0631 \u0627\u0644\u0645\u0647\u0646\u064a" \u0648\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u062a\u062d\u0641\u0638 \u064a\u0641\u0631\u0636 \u0639\u0644\u0649 \u0627\u0644\u0623\u0633\u062a\u0627\u0630:',B.a0o,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0639\u062f\u0645 \u0625\u0641\u0634\u0627\u0621 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0648\u0627\u0644\u0623\u0633\u0631\u0627\u0631 \u0627\u0644\u062a\u064a \u064a\u0637\u0644\u0639 \u0639\u0644\u064a\u0647\u0627 \u0628\u062d\u0643\u0645 \u0645\u0645\u0627\u0631\u0633\u062a\u0647 \u0627\u0644\u0645\u0647\u0646\u064a\u0629 \u0625\u0644\u0627 \u0628\u0631\u062e\u0635\u0629 \u0623\u0648 \u0648\u0627\u062c\u0628 \u0642\u0627\u0646\u0648\u0646\u064a.",u.C)
B.a2E=s(["\u0631\u0626\u064a\u0633 \u062c\u0645\u0639\u064a\u0629 \u0627\u0644\u0622\u0628\u0627\u0621.","\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0628\u0635\u0641\u062a\u0647 \u0631\u0626\u064a\u0633\u0627\u064b \u0644\u0645\u0643\u062a\u0628\u0647\u0627 \u0627\u0644\u062a\u0646\u0641\u064a\u0630\u064a.","\u0627\u0644\u0645\u0641\u062a\u0634 \u0627\u0644\u0645\u0624\u0637\u0631 \u0644\u0644\u0642\u0637\u0627\u0639.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aug=new A.e("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'66. "\u062c\u0645\u0639\u064a\u0629 \u062f\u0639\u0645 \u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0646\u062c\u0627\u062d" (GSES) \u062a\u064f\u062d\u062f\u062b \u0628\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629 \u0648\u064a\u0631\u0623\u0633\u0647\u0627 \u062d\u0643\u0645\u0627\u064b \u0648\u0628\u0634\u0643\u0644 \u062a\u0644\u0642\u0627\u0626\u064a:',B.a2E,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0628\u0635\u0641\u062a\u0647 \u0631\u0626\u064a\u0633\u0627\u064b \u0644\u0645\u0643\u062a\u0628\u0647\u0627 \u0627\u0644\u062a\u0646\u0641\u064a\u0630\u064a.",u.C)
B.Vz=s(["12 \u0623\u0633\u0628\u0648\u0639\u0627\u064b.","14 \u0623\u0633\u0628\u0648\u0639\u0627\u064b.","16 \u0623\u0633\u0628\u0648\u0639\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
