B.any=new A.e("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u0645\u0641\u0647\u0648\u0645 \xab\u0623\u0641\u0642 \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631\xbb \u0623\u0648 \xab\u0623\u0641\u0642 \u0627\u0644\u062a\u0648\u0642\u0639\xbb \u0645\u0631\u062a\u0628\u0637 \u0628\u0640:",B.a22,3,"\u062c\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u062a\u0644\u0642\u064a \u0639\u0646\u062f \u064a\u0627\u0648\u0633: \u0627\u0644\u0642\u0627\u0631\u0626 \u064a\u062d\u0631\u0643 \u0645\u0639\u0627\u0631\u0641\u0647 \u0627\u0644\u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0642\u0631\u0627\u0621\u0627\u062a\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0644\u064a\u0635\u0648\u063a \u0627\u0646\u062a\u0638\u0627\u0631\u0627\u062a\u0647 \u062d\u0648\u0644 \u0627\u0644\u0646\u0635 (\u0623\u0641\u0642 \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631/\u0623\u0641\u0642 \u0627\u0644\u062a\u0648\u0642\u0639).",null)
B.a8C=s(["\u0645\u062a\u0644\u0642\u064a\u0627\u064b \u0633\u0644\u0628\u064a\u0627\u064b \u064a\u0643\u062a\u0641\u064a \u0628\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u0645\u0624\u0644\u0641","\u0630\u0627\u062a\u0627\u064b \u0646\u0635\u064a\u0629 \u062a\u0633\u0647\u0645 \u0628\u0641\u0639\u0627\u0644\u064a\u0629 \u0641\u064a \u0628\u0646\u0627\u0621 \u0645\u0639\u0646\u0649 \u0627\u0644\u0646\u0635\u060c \u0641\u0627\u0644\u0645\u0639\u0646\u0649 \u0646\u062a\u0627\u062c \u0644\u0642\u0627\u0621 \u0646\u0635 \u0627\u0644\u0642\u0627\u0631\u0626 \u0648\u0646\u0635 \u0627\u0644\u0645\u0624\u0644\u0641","\u0646\u0627\u0642\u062f\u0627\u064b \u064a\u0642\u0648\u0651\u0645 \u0627\u0644\u0646\u0635 \u0627\u0644\u0623\u062f\u0628\u064a \u0641\u0642\u0637","\u0645\u0633\u062a\u0642\u0628\u0644\u0627\u064b \u064a\u062d\u0641\u0638 \u0645\u0639\u0646\u0649 \u0627\u0644\u0646\u0635 \u0643\u0645\u0627 \u0623\u0645\u0644\u0627\u0647 \u0627\u0644\u0645\u0624\u0644\u0641","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aod=new A.e("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u0633\u0648\u0633\u064a\u0648\u0644\u0648\u062c\u064a\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0639\u0646\u062f \u0631\u0648\u0644\u0627\u0646 \u0628\u0627\u0631\u062a \u062a\u0639\u062a\u0628\u0631 \u0627\u0644\u0642\u0627\u0631\u0626:",B.a8C,1,"\u0628\u0627\u0631\u062a \u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u0642\u0627\u0631\u0626 \xab\u0630\u0627\u062a\u0627\u064b \u0646\u0635\u064a\u0629\xbb \u062a\u0633\u0647\u0645 \u0628\u0641\u0639\u0627\u0644\u064a\u0629 \u0641\u064a \u0628\u0646\u0627\u0621 \u0645\u0639\u0646\u0649 \u0627\u0644\u0646\u0635\u061b \u0641\u0627\u0644\u0645\u0639\u0646\u0649 \u0646\u062a\u0627\u062c \u0644\u0642\u0627\u0621 \u0628\u064a\u0646 \u0646\u0635 \u0627\u0644\u0642\u0627\u0631\u0626 \u0648\u0646\u0635 \u0627\u0644\u0645\u0624\u0644\u0641.",null)
B.a4a=s(["\u0627\u0644\u0623\u0648\u0644\u0649 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 1-3) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 4-6) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0648\u0627\u0644\u062a\u062d\u062f\u062b","\u0627\u0644\u0623\u0648\u0644\u0649 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 1-2) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u0629\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 3-6) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0642\u0631\u0627\u0621\u0629","\u0627\u0644\u0623\u0648\u0644\u0649 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 1-3) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0648\u0627\u0644\u062a\u062d\u062f\u062b\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 4-6) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0642\u0631\u0627\u0621\u0629","\u0627\u0644\u0623\u0648\u0644\u0649 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 1-4) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u062a\u0639\u0628\u064a\u0631\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 5-6) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0642\u0631\u0627\u0621\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.arh=new A.e("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u064a\u062a\u062f\u0631\u062c \u062a\u0642\u062f\u064a\u0645 \u062a\u0639\u0644\u0645 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0641\u064a \u0627\u0644\u0633\u0644\u0643 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u0639\u0628\u0631 \u0645\u0631\u062d\u0644\u062a\u064a\u0646:",B.a4a,2,"\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u062b\u0644\u0627\u062b\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u062a\u0639\u062a\u0645\u062f \u0645\u062f\u062e\u0644 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0648\u0627\u0644\u062a\u062d\u062f\u062b\u060c \u0648\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0639\u0644\u064a\u0627 (4\u060c 5\u060c 6) \u062a\u0639\u062a\u0645\u062f \u0645\u062f\u062e\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629.",u.L)
B.Ye=s(["\u062e\u0627\u062a\u0645\u0629 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0645\u0628\u0643\u0631 \u0644\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0645\u062d\u0637\u0629 \u0645\u0647\u0645\u0629 \u0644\u062f\u0639\u0645 \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0629 \u0648\u062a\u062b\u0628\u064a\u062a\u0647\u0627 \u0648\u0625\u063a\u0646\u0627\u0626\u0647\u0627","\u0628\u062f\u0627\u064a\u0629 \u0645\u0631\u062d\u0644\u0629 \u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0648\u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0623\u0631\u0628\u0639","\u0645\u0631\u062d\u0644\u0629 \u0627\u0646\u062a\u0642\u0627\u0644\u064a\u0629 \u0648\u062a\u0648\u0637\u0626\u0629 \u0644\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0645\u0648\u0627\u0644\u064a\u0629","\u0645\u062d\u0637\u0629 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u062c\u064a\u062f \u0644\u0644\u0625\u0634\u0647\u0627\u062f \u0648\u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0625\u0644\u0649 \u0627\u0644\u062b\u0627\u0646\u0648\u064a \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u064a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.akU=new A.e("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u062a\u0639\u062f \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062b\u0627\u0644\u062b\u0629 \u0645\u0646 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u060c \u0641\u064a \u0647\u0646\u062f\u0633\u0629 \u0645\u0646\u0627\u0647\u062c \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629:",B.Ye,0,"\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062b\u0627\u0644\u062b\u0629 \u062e\u0627\u062a\u0645\u0629 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0645\u0628\u0643\u0631 \u0644\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0645\u062d\u0637\u0629 \u0645\u0647\u0645\u0629 \u0641\u064a \u062f\u0639\u0645 \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u062a\u064a\u0646 \u0627\u0644\u0623\u0648\u0644\u0649 \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0648\u062a\u062b\u0628\u064a\u062a\u0647\u0627 \u0648\u0625\u063a\u0646\u0627\u0626\u0647\u0627.",u.L)
B.acM=s(["\u062e\u0627\u062a\u0645\u0629 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0645\u0628\u0643\u0631 \u0644\u0644\u0642\u0631\u0627\u0621\u0629","\u0645\u0631\u062d\u0644\u0629 \u0627\u0646\u062a\u0642\u0627\u0644\u064a\u0629 \u0648\u062a\u0648\u0637\u0626\u0629 \u0644\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0645\u0648\u0627\u0644\u064a\u0629 \u0627\u0644\u0645\u062a\u0645\u062b\u0644\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u062a\u064a\u0646 \u0627\u0644\u062e\u0627\u0645\u0633\u0629 \u0648\u0627\u0644\u0633\u0627\u062f\u0633\u0629","\u0628\u062f\u0627\u064a\u0629 \u0645\u062f\u062e\u0644 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0648\u0627\u0644\u062a\u062d\u062f\u062b","\u0645\u0631\u062d\u0644\u0629 \u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.as1=new A.e("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u062a\u0639\u062f \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0631\u0627\u0628\u0639\u0629 \u0645\u0646 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u060c \u0641\u064a \u0647\u0646\u062f\u0633\u0629 \u0645\u0646\u0627\u0647\u062c \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629:",B.acM,1,"\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0631\u0627\u0628\u0639\u0629 \u0645\u0631\u062d\u0644\u0629 \u0627\u0646\u062a\u0642\u0627\u0644\u064a\u0629 \u0648\u062a\u0648\u0637\u0626\u0629 \u0644\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0645\u0648\u0627\u0644\u064a\u0629 \u0627\u0644\u0645\u062a\u0645\u062b\u0644\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u062a\u064a\u0646 \u0627\u0644\u062e\u0627\u0645\u0633\u0629 \u0648\u0627\u0644\u0633\u0627\u062f\u0633\u0629.",u.L)
B.a69=s(["\u0633\u062a \u0648\u062d\u062f\u0627\u062a \u062f\u0631\u0627\u0633\u064a\u0629 \u0645\u0648\u0632\u0639\u0629 \u0628\u0627\u0644\u062a\u0633\u0627\u0648\u064a \u0639\u0644\u0649 \u0627\u0644\u0623\u0633\u062f\u0648\u0633\u064a\u0646\u060c \u062e\u0645\u0633\u0629 \u0623\u0633\u0627\u0628\u064a\u0639 \u0644\u0643\u0644 \u0648\u062d\u062f\u0629","\u0623\u0631\u0628\u0639 \u0648\u062d\u062f\u0627\u062a \u062f\u0631\u0627\u0633\u064a\u0629\u060c \u0633\u062a\u0629 \u0623\u0633\u0627\u0628\u064a\u0639 \u0644\u0643\u0644 \u0648\u062d\u062f\u0629","\u062e\u0645\u0633 \u0648\u062d\u062f\u0627\u062a \u062f\u0631\u0627\u0633\u064a\u0629\u060c \u062e\u0645\u0633\u0629 \u0623\u0633\u0627\u0628\u064a\u0639 \u0644\u0643\u0644 \u0648\u062d\u062f\u0629","\u0633\u062a \u0648\u062d\u062f\u0627\u062a \u062f\u0631\u0627\u0633\u064a\u0629\u060c \u0623\u0631\u0628\u0639\u0629 \u0623\u0633\u0627\u0628\u064a\u0639 \u0644\u0643\u0644 \u0648\u062d\u062f\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.amD=new A.e("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u064a\u0646\u062a\u0638\u0645 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0633\u0646\u0648\u064a \u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0628\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0639\u0628\u0631:",B.a69,0,"\u0648\u0631\u062f \u0641\u064a \u062f\u0644\u064a\u0644 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629: \u064a\u0646\u062a\u0638\u0645 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0633\u0646\u0648\u064a \u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0639\u0628\u0631 \u0633\u062a \u0648\u062d\u062f\u0627\u062a \u062f\u0631\u0627\u0633\u064a\u0629 \u0645\u0648\u0632\u0639\u0629 \u0628\u0627\u0644\u062a\u0633\u0627\u0648\u064a \u0639\u0644\u0649 \u0627\u0644\u0623\u0633\u062f\u0648\u0633\u064a\u0646\u060c \u062a\u0636\u0645 \u0643\u0644 \u0648\u062d\u062f\u0629 \u062e\u0645\u0633\u0629 \u0623\u0633\u0627\u0628\u064a\u0639.",u.T)
B.VH=s(["\u0627\u0633\u062a\u0636\u0645\u0627\u0631 \u0627\u0644\u0628\u0646\u064a\u0629 \u0623\u0648\u0644\u0627\u064b: \u0627\u0644\u0644\u063a\u0629 \u0623\u0633\u0628\u0642 \u0645\u0646 \u0627\u0644\u0642\u0648\u0627\u0639\u062f","\u0627\u0644\u062a\u0635\u0631\u064a\u062d \u0628\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0642\u0628\u0644 \u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u0644\u063a\u0629 \u0648\u0627\u0633\u062a\u0639\u0645\u0627\u0644\u0647\u0627","\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0646\u0647\u0627\u0626\u064a\u0627\u064b \u0641\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629","\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0645\u0646\u0641\u0635\u0644\u0629 \u0639\u0646 \u0627\u0644\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u0644\u063a\u0648\u064a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.akB=new A.e("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u0645\u0628\u062f\u0623 \xab\u0627\u0644\u0625\u0636\u0645\u0627\u0631 \u0648\u0627\u0644\u062a\u0635\u0631\u064a\u062d\xbb \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u064a\u0639\u0646\u064a:",B.VH,0,"\u0645\u0628\u062f\u0623 \u0627\u0644\u0625\u0636\u0645\u0627\u0631 \u0648\u0627\u0644\u062a\u0635\u0631\u064a\u062d: \u0627\u0644\u0644\u063a\u0629 \u0623\u0633\u0628\u0642 \u0645\u0646 \u0627\u0644\u0642\u0648\u0627\u0639\u062f\u061b \u062a\u0633\u062a\u0636\u0645\u0631 \u0627\u0644\u0628\u0646\u064a\u0629 \u0623\u0648\u0644\u0627\u064b (\u0627\u0633\u062a\u0636\u0645\u0627\u0631 \u0627\u0644\u0628\u0646\u064a\u0629) \u062b\u0645 \u064a\u064f\u0635\u0631\u064e\u0651\u062d \u0628\u0627\u0644\u0642\u0627\u0639\u062f\u0629.",u.T)
B.a1c=s(["\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0627\u0646\u063a\u0645\u0627\u0633 \u0627\u0644\u0644\u063a\u0648\u064a \u0641\u064a \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u064a\u0648\u0645\u064a \u0641\u0642\u0637","\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u062c\u0627\u0644 \u0627\u0644\u0630\u064a \u062a\u062a\u0645\u062d\u0648\u0631 \u062d\u0648\u0644\u0647 \u0645\u062e\u062a\u0644\u0641 \u062f\u0631\u0648\u0633 \u0627\u0644\u0648\u062d\u062f\u0629\u060c \u0648\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0647\u064a\u0643\u0644\u064a \u0644\u0644\u062d\u0635\u0635 \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629 \u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0645\u0627\u062f\u0629","\u0645\u0633\u062a\u0648\u0649 \u0631\u0628\u0637 \u0627\u0644\u0645\u0627\u062f\u0629 \u0628\u0627\u0644\u0645\u062c\u0627\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a \u0641\u0642\u0637","\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0630\u0627\u062a\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645(\u0629) \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqW=new A.e("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u0645\u0628\u062f\u0623 \xab\u0627\u0644\u062a\u0643\u0627\u0645\u0644\xbb \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u064a\u062a\u062c\u0644\u0649 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649:",B.a1c,1,"\u0635 10: \u0645\u0628\u062f\u0623 \u0627\u0644\u062a\u0643\u0627\u0645\u0644 \u064a\u062a\u062c\u0644\u0649 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u064a\u064a\u0646 \u0647\u0627\u0645\u064a\u0646: \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u062c\u0627\u0644 \u0627\u0644\u0630\u064a \u062a\u062a\u0645\u062d\u0648\u0631 \u062d\u0648\u0644\u0647 \u0645\u062e\u062a\u0644\u0641 \u062f\u0631\u0648\u0633 \u0627\u0644\u0648\u062d\u062f\u0629\u060c \u0648\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0647\u064a\u0643\u0644\u064a \u0644\u0644\u062d\u0635\u0635 \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629 \u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0645\u0627\u062f\u0629.",u.T)
B.a3O=s(["\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642\u060c \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\u060c \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u062a\u0642\u0648\u064a\u0645 \u0648\u062f\u0639\u0645","\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\u060c \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629","\u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642\u060c \u062a\u0642\u0648\u064a\u0645 \u0648\u062f\u0639\u0645\u060c \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a","\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642\u060c \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aqL=new A.e("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u062a\u064f\u0646\u062c\u064e\u0632 \u0627\u0644\u062d\u0635\u0629 \u0645\u0646 \u0645\u0643\u0648\u0651\u0646 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0628\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0623\u0648\u0644 (\u0627\u0644\u0648\u0639\u064a \u0627\u0644\u0635\u0648\u062a\u064a) \u0648\u0641\u0642 \u0627\u0644\u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629:",B.a3O,0,"\u0645\u0631\u0627\u062d\u0644 \u0645\u062d\u0648\u0631 \u0627\u0644\u0648\u0639\u064a \u0627\u0644\u0635\u0648\u062a\u064a \u0628\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0623\u0648\u0644: \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642\u060c \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\u060c \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u062a\u0642\u0648\u064a\u0645 \u0648\u062f\u0639\u0645.",null)
