B.Y8=s(["\u062a\u0639\u0628\u0626\u0629 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0648\u0627\u0633\u062a\u062d\u0636\u0627\u0631\u0647\u0627 \u0644\u0631\u0628\u0637\u0647\u0627 \u0628\u0627\u0644\u062c\u062f\u064a\u062f","\u062a\u0648\u0638\u064a\u0641 \u0627\u0644\u0643\u0641\u0627\u064a\u0629 \u0648\u062a\u0637\u0628\u064a\u0642\u0647\u0627 \u0645\u0646 \u0623\u062c\u0644 \u0627\u0644\u062a\u0645\u0643\u0646 \u0645\u0646\u0647\u0627","\u062a\u0643\u0644\u064a\u0641 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0628\u062d\u0644 \u0648\u0636\u0639\u064a\u0627\u062a \u0645\u0643\u0627\u0641\u0626\u0629 \u0639\u062f\u0629 \u0645\u0631\u0627\u062a","\u0627\u0644\u0631\u0628\u0637 \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u0641 \u0628\u064a\u0646 \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0648\u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645"],t.s)
B.ama=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"\u0623\u062d\u062f \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0628\u0627\u0644\u0643\u0641\u0627\u064a\u0627\u062a \u0647\u0648 '\u0645\u0628\u062f\u0623 \u0627\u0644\u062a\u0648\u0638\u064a\u0641'\u060c \u0648\u064a\u0642\u0635\u062f \u0628\u0647:",B.Y8,1,"\u0645\u0628\u062f\u0623 \u0627\u0644\u062a\u0648\u0638\u064a\u0641 \u064a\u0639\u0646\u064a \u062a\u0648\u0638\u064a\u0641 \u0627\u0644\u0643\u0641\u0627\u064a\u0629 \u0648\u062a\u0637\u0628\u064a\u0642\u0647\u0627 \u0645\u0646 \u0623\u062c\u0644 \u0627\u0644\u062a\u0645\u0643\u0646 \u0645\u0646\u0647\u0627\u060c \u0648\u0647\u0648 \u0623\u062d\u062f \u0627\u0644\u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u062e\u0645\u0633\u0629 \u0627\u0644\u062a\u064a \u062a\u0642\u0648\u0645 \u0639\u0644\u064a\u0647\u0627 \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0628\u0627\u0644\u0643\u0641\u0627\u064a\u0627\u062a \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u0641 \u0648\u0627\u0644\u0631\u0628\u0637 \u0648\u0627\u0644\u0625\u062f\u0645\u0627\u062c (\u0648\u0641\u0642 \u0645\u0644\u062e\u0635 \u0627\u0644\u0645\u0646\u0647\u0627\u062c \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0644\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a).",null)
