B.amk=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'\u0645\u0646 \u0623\u0637\u0644\u0642 \u0639\u0644\u0649 \u0627\u0644\u0639\u0642\u0644 \u062a\u0633\u0645\u064a\u0629 "\u0627\u0644\u0639\u0644\u0628\u0629 \u0627\u0644\u0633\u0648\u062f\u0627\u0621" \u0636\u0645\u0646 \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0629\u061f',B.abb,2,"\u0627\u0644\u0648\u0627\u0637\u0633\u0648\u0646 (1878-1958) \u0627\u0644\u0645\u0624\u0633\u0633 \u0627\u0644\u062d\u0642\u064a\u0642\u064a \u0644\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0629\u060c \u0643\u0627\u0646 \u064a\u0633\u0645\u064a \u0627\u0644\u0639\u0642\u0644 \u0628\u0627\u0644\u0639\u0644\u0628\u0629 \u0627\u0644\u0633\u0648\u062f\u0627\u0621 \u0644\u0623\u0646\u0647 \u0644\u0627 \u064a\u0645\u0643\u0646 \u0631\u0635\u062f\u0647 \u0648\u0645\u0644\u0627\u062d\u0638\u062a\u0647 \u0645\u0628\u0627\u0634\u0631\u0629.",null)
B.a5u=s(["\u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0631\u0628\u0637 \u0627\u0644\u062d\u0631\u0648\u0641 \u0628\u0623\u0635\u0648\u0627\u062a\u0647\u0627 \u0643\u062a\u0627\u0628\u064a\u0627\u064b \u0641\u0642\u0637","\u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0627\u0644\u0635\u0648\u062a\u064a\u0629 \u0641\u064a \u0643\u0644\u0645\u0627\u062a \u0645\u0646\u0637\u0648\u0642\u0629 \u0648\u0627\u0644\u0644\u0639\u0628 \u0628\u0647\u0627 \u0648\u0627\u0633\u062a\u0639\u0645\u0627\u0644\u0647\u0627","\u062d\u0641\u0638 \u0645\u0639\u0627\u0646\u064a \u0627\u0644\u0645\u0641\u0631\u062f\u0627\u062a \u0639\u0646 \u0638\u0647\u0631 \u0642\u0644\u0628","\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0628\u0633\u0631\u0639\u0629 \u0648\u0625\u064a\u0642\u0627\u0639 \u0635\u0648\u062a\u064a \u0645\u0639\u0628\u0631"],t.s)
B.amn=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"\u0645\u0646 '\u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u062e\u0645\u0633\u0629' \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0644\u0644\u0642\u0631\u0627\u0621\u0629 \u0641\u064a \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u060c '\u0627\u0644\u0648\u0639\u064a \u0627\u0644\u0635\u0648\u062a\u064a' \u064a\u0642\u0635\u062f \u0628\u0647:",B.a5u,1,"\u0627\u0644\u0648\u0639\u064a \u0627\u0644\u0635\u0648\u062a\u064a \u0647\u0648 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0627\u0644\u0635\u0648\u062a\u064a\u0629 \u0648\u062a\u0639\u0631\u0641\u0647\u0627 \u0648\u0627\u0644\u0644\u0639\u0628 \u0628\u0647\u0627\u060c \u0648\u0627\u0644\u0648\u0639\u064a \u0628\u0623\u0646 \u0643\u0644 \u0643\u0644\u0645\u0629 \u0645\u0646\u0637\u0648\u0642\u0629 \u062a\u062a\u0631\u0643\u0628 \u0645\u0646 \u0645\u0642\u0627\u0637\u0639 \u0635\u0648\u062a\u064a\u0629 \u0645\u0641\u0631\u062f\u0629 \u0648\u0644\u064a\u0633\u062a \u0648\u062d\u062f\u0629 \u0635\u0648\u062a\u064a\u0629 \u0648\u0627\u062d\u062f\u0629.",null)
B.aa6=s(["\u062f\u0644\u064a\u0644 \u0641\u0634\u0644 \u064a\u062c\u0628 \u0645\u0639\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0639\u0644\u064a\u0647","\u0645\u0624\u0634\u0631 \u062a\u0639\u0644\u0645\u064a \u064a\u062c\u0628 \u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0647 \u0644\u0641\u0647\u0645 \u0645\u0635\u062f\u0631 \u0627\u0644\u0635\u0639\u0648\u0628\u0629 \u0648\u0645\u0639\u0627\u0644\u062c\u062a\u0647\u0627","\u0623\u0645\u0631 \u064a\u062c\u0628 \u062a\u062c\u0627\u0647\u0644\u0647 \u0648\u0639\u062f\u0645 \u0627\u0644\u0627\u0644\u062a\u0641\u0627\u062a \u0625\u0644\u064a\u0647","\u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0627\u0644\u0623\u0633\u0631\u0629 \u0648\u062d\u062f\u0647\u0627 \u0648\u0644\u064a\u0633 \u0627\u0644\u0645\u062f\u0631\u0633\u0629"],t.s)
B.amp=new A.e("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"'\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062e\u0637\u0623' \u062a\u0646\u0637\u0644\u0642 \u0645\u0646 \u0643\u0648\u0646 \u0627\u0644\u062e\u0637\u0623:",B.aa6,1,"\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062e\u0637\u0623 \u062a\u0639\u062a\u0628\u0631 \u0627\u0644\u062e\u0637\u0623 \u062c\u0632\u0621\u0627\u064b \u0637\u0628\u064a\u0639\u064a\u0627\u064b \u0645\u0646 \u0645\u0633\u0627\u0631 \u0627\u0644\u062a\u0639\u0644\u0645\u060c \u0648\u0645\u0635\u062f\u0631\u0627\u064b \u063a\u0646\u064a\u0627\u064b \u0644\u0641\u0647\u0645 \u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a \u0627\u0644\u062e\u0627\u0637\u0626\u0629 \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u060c \u0648\u0646\u0642\u0637\u0629 \u0627\u0646\u0637\u0644\u0627\u0642 \u0644\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629 \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629.",null)
B.a8G=s(["\u0644\u0648\u0646 \u0627\u0644\u0634\u0639\u0631 \u0648\u0637\u0648\u0644\u0647","\u0627\u0644\u0648\u0633\u0637 \u0627\u0644\u0630\u064a \u062a\u0639\u064a\u0634 \u0641\u064a\u0647 (\u0628\u0631\u0651\u064a\u060c \u0645\u0627\u0626\u064a\u060c \u062c\u0648\u064a\u060c \u0628\u0631\u0645\u0627\u0626\u064a)","\u062d\u062c\u0645 \u0627\u0644\u062c\u0633\u0645 \u0641\u0642\u0637","\u0639\u062f\u062f \u0627\u0644\u0623\u0631\u062c\u0644"],t.s)
